// Original Kō lessons. Coverage names are mapped separately in coverage.json.
const commonReadings={'一晩中':'ひとばんじゅう','一日中':'いちにちじゅう','一晩':'ひとばん','一人':'ひとり','二人':'ふたり','一日':'いちにち','三日':'みっか','十五分':'じゅうごふん','一月':'ひとつき'};
const p=(id,purpose,formation,register,restrictions,mistake,examples)=>({id,purpose,formation:[formation],register,restrictions,mistake,examples:examples.map(([text,translation,note,readings={}])=>({text,translation,note,readings:{...Object.fromEntries(Object.entries(commonReadings).filter(([surface])=>text.replace(/[\[\]]/g,'').includes(surface))),...readings}}))});
export default [
p('n3-001','Mark an action as completed, often with care or effort.','Verb stem + 上げる','Neutral','Used with compatible verbs such as 書く, 作る, 焼く; not freely productive.','This completion suffix differs from giving something to someone.',[['招待状を一晩で書き[上げた]。','I finished writing the invitations in one evening.','Completion after effort.'],['祖母は丸いパンを焼き[上げた]。','Grandmother finished baking a round loaf.','A completed product.'],['学生たちは模型を作り[上げた]。','The students completed their model.','Construction reaches its endpoint.']]),
p('n3-002','Explain that an intense feeling or state caused a result.','Noun + のあまり; verb plain form + あまり','Written / neutral','The cause is unusually strong, often leading to an unintended outcome.','For ordinary reasons use ので; あまり emphasizes excess.',[['驚き[のあまり]、声が出なかった。','I was so surprised that I could not speak.','Emotion blocks a reaction.'],['合格を喜ぶ[あまり]、約束の時間を忘れた。','I was so delighted about passing that I forgot our appointment.','An unintended result.'],['緊張[のあまり]、名前を言い間違えた。','I was so nervous that I said my name incorrectly.','Excessive nervousness.']]),
p('n3-003','Emphasize that a degree goes well beyond expectations.','あまりにも + adjective / verb phrase','Neutral, emphatic','Usually conveys surprise, criticism, or a strong emotional response.','Unlike あまり〜ない, this is not a weak negative.',[['この箱は[あまりにも]重い。','This box is far too heavy.','Beyond a manageable weight.'],['説明が[あまりにも]短くて、手順が分からない。','The explanation is so short that I cannot understand the steps.','An excessive shortage.'],['彼の返事は[あまりにも]冷たかった。','His reply was terribly cold.','Emotional evaluation.']]),
p('n3-004','Show that people perform an action mutually.','Verb stem + 合う','Neutral','Requires an action that can be reciprocal or shared.','話し合う means discuss together; it is more than simply speaking simultaneously.',[['困ったときは助け[合おう]。','Let us help one another when things are difficult.','Mutual support.'],['二人で旅行の計画を話し[合った]。','The two of us discussed our travel plans.','Exchange of views.',{"二人":"ふたり"}],['子どもたちは顔を見[合って]笑った。','The children looked at each other and laughed.','Reciprocal looking.']]),
p('n3-005','Offer a sufficient solution or ask what action would work.','Verb ば-form + いい','Neutral','Advice can sound blunt without a softener such as と思います.','It gives a solution, not a general duty like べきだ.',[['寒いなら、窓を閉めれ[ばいい]よ。','If you are cold, you can just close the window.','A simple solution.'],['この書類はどこに出せ[ばいい]ですか。','Where should I submit this document?','Asking for guidance.'],['分からない言葉は辞書で調べれ[ばいい]。','You can look up words you do not understand in a dictionary.','A sufficient action.']]),
p('n3-006','Express regret about an unrealized better choice.','Verb ば-form + よかった','Neutral','Usually looks back on an action taken or not taken.','Use なければよかった to regret doing something.',[['もう少し早く出れ[ばよかった]。','I should have left a little earlier.','Regret about departure.'],['大きいサイズを買え[ばよかった]。','I wish I had bought the larger size.','An alternative purchase.'],['あのメールは送らなけれ[ばよかった]。','I should not have sent that email.','Negative conditional reverses the regret.']]),
p('n3-007','Describe two degrees increasing together.','Verb ば-form + same verb dictionary form + ほど; adjective conditional + adjective + ほど','Neutral','Repeat the same predicate; な-adjectives use なら〜なほど.','The second half describes a changing degree, not simply the next event.',[['読め[ば]読む[ほど]、この本が好きになる。','The more I read this book, the more I like it.','Repeated experience increases appreciation.'],['荷物は軽けれ[ば]軽い[ほど]いい。','The lighter the luggage, the better.','Degree of lightness.'],['町が静か[なら]静かな[ほど]、よく眠れる。','The quieter the town is, the better I can sleep.','な-adjective pattern.']]),
p('n3-008','Imagine a better result under a condition that is not met.','Conditional ば-clause + result + のに','Neutral','Often expresses regret, disappointment, or a wish.','のに here expresses an unrealized result, not an actual contradiction.',[['車があれ[ば]、海へ行ける[のに]。','If I had a car, I could go to the sea.','The speaker has no car available.'],['もう少し安けれ[ば]、買う[のに]。','If it were a little cheaper, I would buy it.','Current price prevents buying.'],['住所が分かれ[ば]、手紙を送れた[のに]。','If I had known the address, I could have sent a letter.','A missed past opportunity.']]),
p('n3-009','Point out that something only happens or has only one aspect, often with an unsatisfactory result.','Noun + ばかりで; verb plain form + ばかりで','Neutral','Frequently followed by a negative consequence or missing alternative.','With ongoing repeated behavior, use てばかりいる.',[['この店は高い品[ばかりで]、何も買えなかった。','This shop had only expensive items, so I could not buy anything.','Limited selection.'],['弟は文句を言う[ばかりで]、手伝わない。','My brother only complains and does not help.','Words without action.'],['説明は専門用語[ばかりで]、理解できない。','The explanation is full of technical terms, so I cannot understand it.','An unhelpful imbalance.']]),
p('n3-010','Add a second fact beyond the first: not only A but also B.','Plain form + ばかりでなく; noun / な-adjective + である + ばかりでなく','Formal / written','The two facts should build the same argument; も often marks the added item.','Do not use this to contrast two opposing facts.',[['彼女は歌う[ばかりでなく]、曲も作る。','She not only sings but also writes music.','Two abilities.'],['この道は狭い[ばかりでなく]、夜は暗い。','This road is not only narrow but also dark at night.','Two concerns.'],['彼は医師である[ばかりでなく]、作家でもある。','He is not only a doctor but also a writer.','Two roles.']]),
p('n3-011','State what someone ought to do based on a principle or responsibility.','Verb dictionary form + べきだ; する → するべき / すべき','Neutral / firm','Strong advice can sound judgmental, especially toward a superior.','Use はず for an expectation; べき expresses an obligation or recommendation.',[['約束は守る[べきだ]。','You should keep your promises.','A general principle.'],['まず本人に確認する[べきだ]と思う。','I think we should check with the person first.','A reasoned recommendation.'],['この問題は全員で考える[べきだ]。','Everyone should think about this issue.','Shared responsibility.']]),
p('n3-012','State that an action is wrong or should be avoided.','Verb dictionary form + べきではない','Neutral / firm','A moral or practical judgment, rather than a simple prohibition sign.','Attach to the affirmative dictionary form, not the negative verb.',[['人を見た目だけで判断する[べきではない]。','You should not judge people only by their appearance.','A principle about fairness.'],['確認せずに情報を広める[べきではない]。','We should not spread information without checking it.','Responsible communication.'],['疲れているときに無理をする[べきではない]。','You should not push yourself when you are tired.','A practical warning.']]),
p('n3-013','Deny that something is especially true or a particular concern.','別に + negative predicate','Conversational','Can sound dismissive depending on tone; not necessarily complete indifference.','Keep the negative predicate even when English uses “not particularly.”',[['[別に]怒ってはい[ない]。','I am not particularly angry.','Correcting an impression.'],['明日は[別に]予定が[ない]。','I do not have any particular plans tomorrow.','No specific commitment.'],['この席でなくても[別に]構わ[ない]。','I do not particularly mind sitting somewhere else.','No special preference.']]),
p('n3-014','Say that an event happens again after a stated interval.','Duration + ぶりに + event','Neutral','The event occurred before; use 初めて for a first occurrence.','三年ぶり means after three years, not for three years.',[['五年[ぶりに]故郷へ帰った。','I returned to my hometown for the first time in five years.','An interval since the last return.'],['久し[ぶりに]父と散歩した。','I took a walk with my father for the first time in ages.','An unspecified long interval.'],['二週間[ぶりに]晴れた。','It cleared up for the first time in two weeks.','Weather returns after a gap.']]),
p('n3-015','Mark an activity as in progress during its duration.','Activity noun + 中（ちゅう）','Neutral / notices','For all of a time span, 中 may be read じゅう; this point concerns ongoing activities.','会議中 means during a meeting, not necessarily all day.',[['ただいま会議[中]です。','We are currently in a meeting.','An activity in progress.'],['工事[中]なので、この入口は使えません。','This entrance cannot be used because construction is underway.','A temporary ongoing state.'],['授業[中]は携帯電話をしまってください。','Please put your phone away during class.','Throughout an activity.']]),
p('n3-016','Describe an amount or degree as far as a limit allows.','Verb plain form / potential form + だけ','Neutral','Often pairs with a repeated verb, such as 食べたいだけ食べる.','This degree use is broader than noun + だけ meaning only.',[['好きな[だけ]休んでいい。','You may rest as much as you like.','The amount follows preference.'],['持てる[だけ]持ってきた。','I brought as much as I could carry.','A limit of capacity.'],['必要な[だけ]コピーしてください。','Please make as many copies as you need.','A limit set by need.']]),
p('n3-017','Include another fact in addition to the first.','Plain form + だけでなく; noun + だけでなく; な-adjective + なだけでなく','Neutral','Often pair the second item with も to make the addition clear.','Use な before だけ with a な-adjective, but not with an ordinary noun.',[['この公園は広い[だけでなく]、静かだ。','This park is not only spacious but also quiet.','Two qualities.'],['母[だけでなく]、父も料理が得意だ。','Not only my mother but also my father is good at cooking.','Two people.'],['この道具は便利な[だけでなく]、丈夫だ。','This tool is not only useful but also durable.','な-adjective connection.']]),
p('n3-018','Introduce a contrast or a gentle reservation.','Sentence + だけど; noun / な-adjective + だけど','Conversational','At sentence start, it responds to a previous statement.','With verbs and い-adjectives inside a sentence use けど rather than attaching だけど directly.',[['明日は休み[だけど]、会社へ行く。','Tomorrow is a day off, but I am going to the office.','Contrast after a noun.'],['あの店は便利[だけど]、少し高い。','That shop is convenient, but a little expensive.','Contrast after a な-adjective.'],['行きたい。[だけど]、今日は時間がない。','I want to go. But I do not have time today.','A new sentence introduces the reservation.']]),
p('n3-019','Describe something covered in or full of undesirable things.','Noun + だらけ','Neutral, usually negative','Best with scattered marks, errors, or unwanted items; いっぱい is more neutral.','Do not normally use だらけ for a pleasant abundance.',[['靴が泥[だらけ]になった。','My shoes became covered in mud.','Unwanted material on a surface.'],['この作文は間違い[だらけ]だ。','This composition is full of mistakes.','Many flaws.'],['古い机は傷[だらけ]だった。','The old desk was covered in scratches.','Marks across an object.']]),
p('n3-020','Say that a result holds regardless of how great a degree becomes.','どんなに + ても-form','Neutral','The degree is open-ended; the conclusion remains unchanged.','Use an adjective or verb that naturally varies in degree.',[['[どんなに]忙しく[ても]、朝ご飯は食べる。','No matter how busy I am, I eat breakfast.','A fixed habit.'],['[どんなに]練習し[ても]、まだ緊張する。','No matter how much I practice, I still get nervous.','Effort does not remove the feeling.'],['[どんなに]遠く[ても]、会いに行く。','However far away it is, I will go to see you.','Distance does not change the decision.']]),
p('n3-021','Express a firm desire or an obstacle that cannot be overcome.','どうしても + desire / negative potential / necessity','Neutral, emphatic','The predicate determines whether it means at all costs or simply cannot.','どうして asks why; どうしても is an emphatic adverb.',[['[どうしても]この舞台を見たい。','I want to see this performance no matter what.','Strong desire.'],['名前が[どうしても]思い出せない。','I simply cannot remember the name.','An unsuccessful mental effort.'],['今日は[どうしても]帰らなければならない。','I absolutely have to go home today.','An unavoidable need.']]),
p('n3-022','Pretend that a state or action is true.','Plain form + ふりをする; noun + の / な-adjective + な + ふりをする','Neutral','The outward appearance intentionally differs from reality.','Use ふり, not つもり, when someone deliberately acts a part.',[['知らない[ふりをした]。','I pretended not to know.','Hiding knowledge.'],['子どもは寝ている[ふりをしていた]。','The child was pretending to be asleep.','An ongoing performance.'],['平気な[ふりをした]が、本当は怖かった。','I pretended to be fine, but I was actually frightened.','Concealing a feeling.']]),
p('n3-023','Describe a thought or action that occurs unexpectedly.','ふと + perception / thought / small action','Neutral / narrative','Often a brief unplanned moment, rather than a deliberate decision.','突然 emphasizes abruptness; ふと often emphasizes lack of intention.',[['[ふと]昔の友人を思い出した。','I suddenly thought of an old friend.','An unbidden memory.'],['[ふと]窓を見ると、雪が降っていた。','I happened to look out the window and saw snow falling.','An incidental glance.'],['帰り道で[ふと]足を止めた。','On my way home, I stopped without thinking.','A spontaneous small action.']]),
p('n3-024','Describe a recurring tendency, often an unwanted one.','Verb stem / noun + がち','Neutral','Often used for absence, forgetting, illness, or other negative patterns.','It describes a tendency, not necessarily something happening right now.',[['忙しいと朝食を抜き[がち]だ。','When I am busy, I tend to skip breakfast.','A repeated habit.'],['冬は部屋にこもり[がち]になる。','In winter I tend to stay indoors.','A seasonal tendency.'],['最近、彼は欠席[がち]だ。','Recently he has been absent quite often.','A tendency described by a noun.']]),
p('n3-025','Describe something difficult to accept or do emotionally or mentally.','Verb stem + がたい','Formal / written','Common with 信じる, 許す, 忘れる, 理解する; not a general physical inability.','For a stiff lid that is hard to open, にくい is more natural.',[['その説明は信じ[がたい]。','That explanation is hard to believe.','Difficulty accepting a claim.'],['故郷で過ごした夏は忘れ[がたい]。','The summer I spent in my hometown is unforgettable.','An enduring memory.'],['その行為は許し[がたい]。','That behavior is hard to forgive.','A moral judgment.']]),
p('n3-026','Report a slight sign of a condition, usually an unwelcome one.','Verb stem / noun + 気味','Neutral','Often a temporary feeling or early symptom; not a strong established condition.','気味 describes a slight state; がち describes a recurring tendency.',[['今日は少し疲れ[気味]だ。','I feel a little tired today.','A mild present condition.'],['最近、運動不足[気味]です。','I have not been getting quite enough exercise lately.','A slight imbalance.'],['朝から風邪[気味]なので、早く寝る。','I have felt a little under the weather since morning, so I will go to bed early.','An early symptom.']]),
p('n3-027','Apply an event or rule to each unit or recurring interval.','Noun / duration / verb dictionary form + ごとに','Neutral','Emphasizes regular units; distinguish an interval from a total duration.','三日ごとに means every three days, not three times per day.',[['駅[ごとに]乗客が増える。','There are more passengers at each station.','Each location as a unit.'],['二時間[ごとに]休憩する。','We take a break every two hours.','A regular interval.'],['会う[ごとに]、弟は背が伸びている。','Each time I see my younger brother, he has grown taller.','A repeated occasion.']]),
p('n3-028','Show degree by comparing it with an illustrative result.','Plain form + ほど; noun + ほど; な-adjective + なほど','Neutral','The result often serves as an expressive scale, not a literal measurement.','Do not translate every ほど as approximately; this use describes intensity.',[['声が出ない[ほど]驚いた。','I was so surprised that I could not speak.','An extreme reaction.'],['このかばんは子どもでも持てる[ほど]軽い。','This bag is light enough for even a child to carry.','A practical degree.'],['涙が出る[ほど]笑った。','I laughed so much that tears came to my eyes.','A vivid scale.']]),
p('n3-029','Say that one thing does not reach another thing’s degree.','Comparison noun + ほど + negative predicate','Neutral','A negative predicate is needed for the less-than comparison.','AはBほど〜ない means A is less so than B, not the reverse.',[['今日は昨日[ほど]寒く[ない]。','Today is not as cold as yesterday.','Comparing temperatures.'],['この道は大通り[ほど]混んでい[ない]。','This road is not as crowded as the main road.','Comparing traffic.'],['私は姉[ほど]速く泳げ[ない]。','I cannot swim as fast as my older sister.','Comparing ability.']]),
p('n3-030','Describe doing several things or handling an amount at one time.','一度に + quantity / action','Neutral','Contrasts one combined occasion with separate stages.','一度に is at one time; 一度だけ is only once.',[['薬を[一度に]三錠飲んだ。','I took three tablets at one time.','A single dose.'],['全員が[一度に]話すと聞こえない。','I cannot hear if everyone speaks at once.','Simultaneous action.'],['荷物を[一度に]全部運ぶのは難しい。','It is difficult to carry all the luggage in one trip.','One combined load.']]),
p('n3-031','Say that increasing effort or amount does not change the result.','いくら + ても-form','Neutral','Often pairs with a negative or unchanged outcome.','いくら here means however much, rather than asking a price.',[['[いくら]探し[ても]、鍵が見つからない。','However much I search, I cannot find my key.','Unsuccessful effort.'],['[いくら]安く[ても]、使わない物は買わない。','However cheap it is, I do not buy things I will not use.','A firm purchasing rule.'],['[いくら]説明し[ても]、納得してもらえなかった。','No matter how much I explained, I could not convince them.','Repeated explanation changes nothing.']]),
p('n3-032','Describe a change continuing in one direction.','Change verb dictionary form + 一方だ','Neutral / written','Use with verbs of change; commonly, but not always, an unwelcome trend.','It describes an ongoing trend rather than two contrasting sides.',[['物価は上がる[一方だ]。','Prices keep rising.','An upward trend.'],['使わない単語は忘れる[一方だ]。','I keep forgetting words I do not use.','Continuing loss.'],['修理しても、機械の状態は悪くなる[一方だ]。','Even after repairs, the machine keeps getting worse.','Change in one direction.']]),
p('n3-033','Add strong puzzlement or surprise to a question.','一体 + question expression','Neutral / emphatic','Can sound accusatory when directed at another person.','It strengthens a question; it does not answer what caused the event.',[['[一体]何が起きたのですか。','What on earth happened?','Puzzlement about an event.'],['彼は[一体]どこへ行ったのだろう。','Where on earth did he go?','Wondering privately.',{"行っ":"いっ"}],['これは[一体]どう使うんですか。','How on earth do you use this?','Confusion about a tool.']]),
p('n3-034','Call attention to something the listener can also recognize.','Plain sentence + じゃない / じゃないか','Conversational','Intonation and context distinguish this from an ordinary negative.','きれいじゃない can mean either “not pretty” or “isn’t it pretty?”; make context clear.',[['ほら、虹が見える[じゃない]。','Look, you can see a rainbow!','Pointing out a shared discovery.'],['この方法なら簡単にできる[じゃない]。','See, you can do it easily this way.','Recognizing a workable solution.'],['昨日も同じことを言った[じゃない]か。','I told you the same thing yesterday, remember?','A reminder with a firm tone.']]),
p('n3-035','Offer an item as a loose example rather than a fixed choice.','Noun + か何か','Conversational','Leaves the alternative unspecified; useful for offers and guesses.','For explicit alternatives use AかB rather than 何か.',[['お茶[か何か]飲みませんか。','Would you like some tea or something?','An open offer.'],['紙[か何か]に書いておいて。','Write it on some paper or something.','The material is flexible.'],['外で猫[か何か]が鳴いている。','There is a cat or something crying outside.','An uncertain identification.']]),
p('n3-036','Describe an action begun but not completed.','Verb stem + かける / かけの + noun','Neutral','Some verbs also use this for being on the verge of an event.','かけ does not mean the action is finished.',[['読み[かけの]本を机に置いた。','I put the book I had started reading on the desk.','An unfinished object.'],['言い[かけた]言葉を飲み込んだ。','I swallowed the words I had started to say.','An interrupted action.'],['階段で転び[かけた]。','I nearly fell on the stairs.','An event almost happened.']]),
p('n3-037','Give an approximate span across time or space.','Noun + から + noun + にかけて','Neutral / forecasts','The boundaries are often broad rather than exact.','Use から〜まで when an exact endpoint matters.',[['夜[から]朝[にかけて]雨が降る。','It will rain from night into the morning.','An approximate time span.'],['肩[から]背中[にかけて]痛みがある。','I have pain from my shoulder across my back.','A continuous area.'],['九州[から]四国[にかけて]強い風が吹く。','Strong winds will blow across Kyushu and Shikoku.','A broad geographic range.']]),
p('n3-038','Describe a substitute or a trade-off.','Verb plain form + 代わりに; noun + の代わりに','Neutral','Context distinguishes replacement from compensation or a contrasting cost.','For serving in someone’s role, に代わって is also common.',[['車の[代わりに]自転車で行った。','I went by bicycle instead of by car.','Replacing a means of transport.',{"行っ":"いっ"}],['私が料理する[代わりに]、弟が皿を洗う。','I cook, and in exchange my brother washes the dishes.','An agreed exchange.'],['この部屋は広い[代わりに]、家賃が高い。','This room is spacious, but the rent is high.','A benefit with a cost.']]),
p('n3-039','Introduce the outcome of a completed process.','Verb past form + 結果; noun + の結果','Neutral / written','The preceding event is treated as a process that produced the result.','結果 is the outcome, not an intention expressed by ために.',[['よく話し合った[結果]、旅行を延期した。','After thorough discussion, we postponed the trip.','A decision after a process.'],['検査の[結果]、異常はなかった。','The examination found no abnormalities.','A finding from a test.'],['毎日練習した[結果]、最後まで弾けるようになった。','As a result of practicing every day, I became able to play to the end.','An acquired ability.']]),
p('n3-040','State the final outcome after developments or uncertainty.','結局 + final outcome','Neutral','Often implies that alternatives or efforts did not change the ending.','Use ついに for reaching a long-awaited milestone; 結局 emphasizes the outcome.',[['迷ったが、[結局]青い方を買った。','I hesitated, but in the end I bought the blue one.','A final choice.'],['何度も電話したが、[結局]連絡は取れなかった。','I called many times, but ultimately could not get in touch.','Effort without success.'],['遠回りしたので、[結局]遅くなった。','We took a detour and ended up being late.','The eventual result.']]),
p('n3-041','Make a firm negative statement: never or by no means.','決して + negative predicate','Neutral / emphatic','Use to deny a possibility, make a promise, or state a strong judgment.','Do not omit the negative predicate.',[['この経験は[決して]忘れ[ない]。','I will never forget this experience.','A firm promise.'],['この道は[決して]安全では[ない]。','This road is by no means safe.','Strong rejection of an assumption.'],['人の秘密は[決して]話してはいけ[ない]。','You must never reveal someone else’s secret.','A strong prohibition.']]),
p('n3-042','Say that an action cannot reach full completion.','Verb stem + 切れない','Neutral','Often the amount or difficulty exceeds capacity; differs from simple inability to begin.','食べ切れない means cannot eat all of it, not cannot eat any.',[['この量は一人では食べ[切れない]。','One person cannot finish this amount of food.','Too much to finish.',{"一人":"ひとり"}],['一日では全部読み[切れない]。','I cannot read all of it in one day.','A time limit.'],['彼には感謝してもし[切れない]。','I cannot thank him enough.','Gratitude beyond full expression.']]),
p('n3-043','Limit an amount or mark an action after which a state has continued.','Noun + きり; verb past form + きり','Neutral','With a past action, the expected following action has not occurred.','二人きり means just two people; たきり describes what has not happened since.',[['今日は家に私一人[きり]だ。','I am the only person at home today.','A limited number.',{"一人":"ひとり"}],['彼は出かけた[きり]、まだ戻らない。','He went out and has not come back yet.','No return after departure.'],['その映画は一度見た[きり]だ。','I have seen that film only once.','One occurrence only.']]),
p('n3-044','Describe carrying an action all the way to completion.','Verb stem + 切る','Neutral','Often emphasizes exhaustion, determination, or consuming the full amount.','This suffix is not interchangeable with physical 切る meaning cut.',[['長い小説を読み[切った]。','I finished reading the long novel.','The entire text.'],['最後まで走り[切った]。','I ran all the way to the finish.','Persistence to the endpoint.'],['今月の予算を使い[切って]しまった。','I used up this month’s budget.','Nothing remains.']]),
p('n3-045','Check a memory or ask oneself to recall a detail.','Plain form / です / でした + っけ','Casual','Use with familiar people or self-directed questions.','It is not a general substitute for polite か when asking new information.',[['会議は何時からだ[っけ]。','What time was the meeting again?','Recalling a schedule.',{"何時":"なんじ"}],['この鍵はどのドアのだ[っけ]。','Which door was this key for again?','A forgotten detail.'],['前にもここに来た[っけ]。','Have I been here before?','Checking one’s own memory.']]),
p('n3-046','Describe movement inward or an action becoming deep or thorough.','Verb stem + 込む','Neutral','Meanings depend on the established compound verb.','Not every verb can combine freely with 込む; learn the compound as a unit.',[['猫が箱に入り[込んだ]。','The cat slipped into the box.','Movement into an interior.'],['将来のことを考え[込んで]いた。','I was deep in thought about the future.','Deep mental involvement.'],['夜になって、急に冷え[込んだ]。','It suddenly grew cold at nightfall.','An intensified state.']]),
p('n3-047','Emphasize the exact person, time, or thing that matters.','Noun / particle phrase + こそ','Neutral, emphatic','Often marks a contrast with other candidates or a previous failed attempt.','こそ adds focus; it does not by itself mean only.',[['今年[こそ]試験に合格したい。','This year, I really want to pass the exam.','Renewed determination.'],['こちら[こそ]、ありがとうございます。','It is I who should thank you.','Returning thanks.'],['困ったとき[こそ]、落ち着いて考えよう。','It is precisely when we are in trouble that we should think calmly.','The crucial occasion.']]),
p('n3-048','Give a concise written instruction or rule.','Verb dictionary form / negative form + こと','Written rules / firm instructions','Common in notices, assignments, and instructions from someone with authority.','This sentence-final use gives a directive; nominalizing こと has other functions.',[['答案には名前を書く[こと]。','Write your name on the answer sheet.','An examination instruction.'],['作業中は手袋を外さない[こと]。','Do not remove your gloves while working.','A safety rule.'],['明日までに資料を読む[こと]。','Read the materials by tomorrow.','An assigned task.']]),
p('n3-049','Give a fact as the basis for an inference or name.','Plain form + ことから; noun / な-adjective + であることから','Neutral / explanatory','The first clause provides evidence or the basis for the conclusion.','It need not describe a direct physical cause.',[['道がぬれている[ことから]、雨が降ったと分かる。','The wet road tells us that it has rained.','Evidence for an inference.'],['形が星に似ている[ことから]、この名が付いた。','It received this name because its shape resembles a star.','The basis of a name.'],['駅に近い[ことから]、この会場が選ばれた。','This venue was chosen because it is close to the station.','A selection criterion.']]),
p('n3-050','Report an established rule, arrangement, or schedule.','Verb dictionary form / negative form + ことになっている','Neutral','Presents an existing arrangement rather than a fresh personal decision.','Use ことにしている for a personal practice you maintain.',[['図書館では飲食しない[ことになっている]。','Eating and drinking are not allowed in the library.','An existing rule.'],['来週から新しい担当者が来る[ことになっている]。','A new person is scheduled to take over next week.','An arrangement already made.'],['鍵は管理人に返す[ことになっている]。','The arrangement is to return the key to the caretaker.','An established procedure.']]),
p('n3-051','Reassure someone that an action is unnecessary.','Verb dictionary form + ことはない','Neutral / reassuring','Often offers advice about an unnecessary worry or response.','Do not confuse with たことがない, which denies experience.',[['そんなに急ぐ[ことはない]よ。','There is no need to hurry so much.','Reducing pressure.'],['失敗を恥じる[ことはない]。','You do not need to be ashamed of failing.','Emotional reassurance.'],['まだ新しいので、買い替える[ことはない]。','It is still new, so there is no need to replace it.','Avoiding unnecessary expense.']]),
p('n3-052','Admit a fact while adding a qualification.','Predicate + ことは + repeated predicate + が / けど','Neutral','Repeat the predicate, changing tense or politeness naturally where needed.','The admission is real; the following clause limits its usefulness or extent.',[['読んだ[ことは]読んだ[が]、よく覚えていない。','I did read it, but I do not remember it well.','Admitting an action with a limit.'],['安い[ことは]安い[が]、すぐ壊れそうだ。','It is cheap, but it looks likely to break quickly.','Price with a reservation.'],['静かな[ことは]静かだ[が]、駅から遠い。','It is certainly quiet, but it is far from the station.','な-adjective admission.']]),
p('n3-053','Use an extreme example or a small minimum to show degree.','Plain form / noun + くらい / ぐらい','Neutral / conversational','Can emphasize how intense something is or how modest a minimum is.','Context distinguishes this use from approximate quantities.',[['眠れない[くらい]うれしかった。','I was so happy I could not sleep.','Intensity of emotion.'],['名前[ぐらい]は覚えている。','I remember at least the name.','A modest minimum.'],['立っていられない[くらい]風が強い。','The wind is so strong I cannot stay standing.','Degree illustrated by a result.']]),
p('n3-054','Criticize a mismatch between someone’s circumstances and behavior.','Plain form + くせに; noun + の / な-adjective + な + くせに','Conversational, critical','Often targets the same person in both clauses; can sound insulting.','Use のに for a more neutral contrast.',[['知っている[くせに]、教えてくれない。','Even though he knows, he will not tell me.','Criticism of withholding information.'],['自分は遅れる[くせに]、人には厳しい。','They are strict with others even though they themselves are late.','A double standard.'],['怖い[くせに]、平気な顔をしている。','Although she is scared, she is acting unconcerned.','Pointing out a pretense.']]),
p('n3-055','Introduce a vivid likeness or an almost complete resemblance.','まるで + noun + のよう / みたい; まるで + negative','Neutral','With a negative predicate it can mean completely not, rather than a comparison.','The comparison is figurative; it need not be literally true.',[['この雲は[まるで]大きな船のようだ。','This cloud looks just like a huge ship.','A visual comparison.'],['彼女は[まるで]何もなかったように笑った。','She smiled as if nothing had happened.','A comparison of behavior.'],['説明を聞いたが、[まるで]分からない。','I heard the explanation, but I do not understand it at all.','Complete lack of understanding.']]),
p('n3-056','Express disbelief or introduce an unlikely possibility.','まさか + statement / negative expectation','Conversational / expressive','May stand alone as a surprised response; often pairs with とは or ないだろう.','It expresses the speaker’s expectation, not objective impossibility.',[['[まさか]ここで会うとは思わなかった。','I never imagined I would meet you here.','A surprising encounter.'],['[まさか]鍵を忘れたんじゃないでしょうね。','Surely you have not forgotten the key?','Checking an unwelcome possibility.'],['[まさか]雪になるとは。','I never thought it would turn to snow.','A surprised unfinished exclamation.']]),
p('n3-057','Say that an event occurs only rarely.','めったに + negative predicate','Neutral','Allows occasional exceptions; less absolute than 決して〜ない.','Keep the negative form: めったに行かない.',[['平日は[めったに]外食し[ない]。','I rarely eat out on weekdays.','Low frequency.'],['この町では雪は[めったに]降ら[ない]。','It rarely snows in this town.','An unusual event.'],['祖父は[めったに]怒ら[ない]。','My grandfather rarely gets angry.','A generally calm temperament.']]),
p('n3-058','List two coexisting characteristics with emphasis on both.','Aも + predicate ば-form + Bも + predicate','Neutral / written','The ば is additive here, not a condition.','Do not read the second characteristic as the result of the first.',[['彼女は歌[も]歌えれ[ば]、ピアノ[も]弾ける。','She can both sing and play the piano.','Two abilities.'],['この町は海[も]あれ[ば]、山[も]ある。','This town has both sea and mountains.','Two features.'],['参加者には学生[も]いれ[ば]、会社員[も]いる。','The participants include both students and company employees.','Two groups.']]),
p('n3-059','Raise a possibility without claiming certainty.','もしかしたら + かもしれない / speculative predicate','Neutral','Often introduces a tentative guess about an uncertain situation.','もしかしたら is a possibility marker, not a condition meaning if you can.',[['[もしかしたら]明日は休みかもしれない。','Perhaps tomorrow is a day off.','Uncertain schedule.'],['[もしかしたら]この鍵かもしれない。','Maybe this is the right key.','A tentative candidate.'],['[もしかしたら]道を間違えたのかな。','Perhaps we took the wrong road.','A tentative explanation.']]),
p('n3-060','Emphasize an imagined condition, including an unlikely one.','もしも + たら-form','Neutral','The main clause can express a question, intention, or hypothetical result.','もしも strengthens the hypothetical frame; it is not required by たら.',[['[もしも]宝くじが当たっ[たら]、店を開きたい。','If I happened to win the lottery, I would like to open a shop.','A speculative wish.'],['[もしも]電車が止まっ[たら]、バスで帰ろう。','If the trains stop, let us go home by bus.','A backup plan.'],['[もしも]一日自由だっ[たら]、何をしますか。','If you had a whole day free, what would you do?','An imagined choice.']]),
p('n3-061','Identify the audience something was made or intended for.','Audience noun + 向け; noun + 向けの + noun','Neutral','Emphasizes intended users rather than an inherent suitability.','A product can be 子ども向け yet not suit every child.',[['これは初心者[向けの]辞書です。','This is a dictionary for beginners.','Intended audience.'],['外国人[向けに]町の地図を作った。','We made a town map for foreign visitors.','A target readership.'],['子ども[向けの]番組を録画した。','I recorded a program intended for children.','A designed audience.']]),
p('n3-062','Describe what someone or something is suited to.','Noun + 向き; noun + 向きの + noun','Neutral','Focuses on suitability, whether or not it was designed for that purpose.','向け names the target audience; 向き evaluates the fit.',[['この靴は山歩き[向き]だ。','These shoes are suited to mountain walking.','Practical suitability.'],['私は接客[向き]ではないと思う。','I do not think I am suited to customer service.','A personal fit.'],['これは夏[向きの]軽い布だ。','This is a light fabric suitable for summer.','Suitability for a season.']]),
p('n3-063','Replace an expected description or choice with a more fitting one.','むしろ + preferred judgment / alternative','Neutral','Often follows a denied or qualified first interpretation.','It marks a better-fitting alternative, not simply another added option.',[['怒るより、[むしろ]心配している。','Rather than being angry, I am worried.','Correcting an emotional description.'],['この仕事は難しいが、[むしろ]面白い。','This work is difficult, but that actually makes it interesting.','An unexpected positive evaluation.'],['車より[むしろ]電車で行きたい。','I would rather go by train than by car.','A preference.']]),
p('n3-064','Admit a state that contrasts with the following action or fact.','Verb stem / adjective / noun + ながらも','Written / reflective','This concessive use differs from doing two actions simultaneously.','With nouns, familiar phrases such as 子どもながらも are most natural.',[['不安を感じ[ながらも]、申し込んだ。','Although I felt anxious, I applied.','Action despite a feeling.'],['狭い[ながらも]、居心地のよい部屋だ。','Although it is small, it is a comfortable room.','Contrasting qualities.'],['子ども[ながらも]、責任を理解していた。','Although still a child, she understood her responsibility.','Achievement despite age.']]),
p('n3-065','Admit a limited possibility with a reservation.','Negative predicate + ことはない','Neutral / cautious','Double negation weakly affirms rather than strongly recommending.','食べられないことはない means it is possible to eat, with some hesitation.',[['食べられ[ないことはない]が、少し辛すぎる。','I can eat it, but it is a little too spicy.','Qualified ability.'],['歩け[ないことはない]けど、遠いよ。','It is possible to walk, but it is far.','Possible but inconvenient.'],['興味が[ないことはない]。','I do have some interest.','A cautious admission.']]),
p('n3-066','State an obligation casually by leaving its consequence understood.','Verb negative form + と','Conversational','Short for ないといけない or ないとだめ; context supplies the need.','This sentence-final use implies must; a full ないと-clause can also mean unless.',[['そろそろ帰ら[ないと]。','I had better go home soon.','The consequence is omitted.'],['明日は早いから、もう寝[ないと]。','I have an early start tomorrow, so I need to sleep now.','A personal obligation.'],['締切までに返事をし[ないと]。','I must reply before the deadline.','A necessary action.']]),
p('n3-067','Describe something as rather impressive or slow to happen.','なかなか + affirmative evaluation / negative predicate','Neutral','With a negative it often means an expected result is difficult to achieve.','なかなかいい is positive; なかなか来ない means does not come readily.',[['この店は[なかなか]いいね。','This is quite a good shop.','Pleasantly surprised evaluation.'],['バスが[なかなか]来ない。','The bus is taking a long time to come.','An expected event is delayed.'],['難しい問題が[なかなか]解けない。','I am having a hard time solving the difficult problem.','A result not easily achieved.']]),
p('n3-068','Present something as an example, sometimes with dismissal or surprise.','Noun + なんか / なんて / など; quoted clause + なんて','Conversational; など is more formal','Tone determines whether the expression is modest, dismissive, or surprised.','なんて can belittle a person or thing; avoid it in respectful descriptions.',[['週末は映画[なんか]どうですか。','How about a movie or something this weekend?','A casual example.'],['私[なんか]には難しすぎます。','It is too difficult for someone like me.','Self-deprecation.'],['一人で完成させた[なんて]、すごい。','It is amazing that you finished it by yourself.','Surprise at a quoted fact.',{"一人":"ひとり"}]]),
p('n3-069','Do an action again to correct or improve its result.','Verb stem + 直す','Neutral','The second attempt repairs or revises the first; not merely a repeated habit.','読み直す is reread; 直す also has an independent repair meaning.',[['住所を書き[直した]。','I rewrote the address.','Correcting written information.'],['聞こえなかったので、聞き[直した]。','I asked again because I had not heard.','Repeating a question.'],['計画を考え[直す]必要がある。','We need to rethink the plan.','Revising a decision.']]),
p('n3-070','Ask for or choose the greatest practical degree.','なるべく + desired action / state','Neutral','Leaves room for practical constraints; less absolute than 必ず.','なるべく早く means as early as possible, not necessarily immediately.',[['[なるべく]早く返事をください。','Please reply as soon as you can.','A practical request.'],['買い物には[なるべく]袋を持っていく。','I take a bag shopping whenever possible.','A flexible habit.'],['説明は[なるべく]短くします。','I will keep the explanation as short as possible.','An effort within constraints.']]),
p('n3-071','Introduce the reason for a preceding claim.','Claim。なぜなら + reason + からだ / のだ','Neutral / explanatory','The reason normally follows, rather than being a question asked of someone.','なぜなら sets up an explanation; なぜ asks why.',[['今日は自転車で行く。[なぜなら]、電車が止まっているからだ。','I will go by bicycle today, because the trains are not running.','Explaining a choice.'],['この案に賛成だ。[なぜなら]、費用が少なくて済むからだ。','I support this proposal, because it keeps costs down.','Supporting an opinion.'],['彼は来られない。[なぜなら]、出張中だからだ。','He cannot come, because he is away on business.','A reason for absence.']]),
p('n3-072','Pass on something heard from another person.','Plain explanatory form + んだって; noun / な-adjective + なんだって','Casual','A conversational hearsay form; does not prove the report true.','The ん belongs to the explanatory form; noun predicates need な.',[['駅前に本屋ができる[んだって]。','I hear a bookshop is opening by the station.','Sharing news.'],['田中さんは明日休み[なんだって]。','Apparently Tanaka is off tomorrow.','A reported schedule.'],['あの映画、面白かった[んだって]。','I heard that film was good.','Passing on a review.']]),
p('n3-073','Make a confident inference from available clues.','Plain form + に違いない; noun / な-adjective stem + に違いない','Neutral / firm','Expresses the speaker’s conviction, not independently verified truth.','Use はず for a reasoned expectation; に違いない stresses certainty of inference.',[['電気がついている。誰かいる[に違いない]。','The light is on. Someone must be there.','A visible clue.'],['毎日練習したのだから、上手になる[に違いない]。','After practicing every day, she is bound to improve.','A confident prediction.'],['この足跡は猫のもの[に違いない]。','These footprints must belong to a cat.','Identifying evidence.']]),
p('n3-074','Describe a result contrary to a prediction, rule, or intention.','Noun + に反して; noun + に反する + noun','Neutral / written','Common with 予想, 期待, 意志, and rules.','Use に対して for a neutral target or contrast; に反して means contrary to.',[['予想[に反して]、会場は静かだった。','Contrary to expectations, the venue was quiet.','An unexpected situation.'],['親の希望[に反して]、彼は海外へ行った。','He went abroad against his parents’ wishes.','Conflicting wishes.',{"行っ":"いっ"}],['規則[に反する]行為は認められない。','Conduct that violates the rules is not permitted.','A noun-modifying form.']]),
p('n3-075','Identify a field in which someone is particularly capable.','Ability / field noun + にかけては','Neutral / evaluative','Usually followed by a positive assessment of skill or strength.','This ability use differs from から〜にかけて, which marks a range.',[['料理[にかけては]、兄にかなわない。','When it comes to cooking, I cannot match my older brother.','A field of expertise.'],['暗算[にかけては]、彼女が一番だ。','She is the best when it comes to mental arithmetic.','A particular strength.'],['体力[にかけては]自信がある。','I am confident when it comes to physical stamina.','Confidence in one area.']]),
p('n3-076','Name the subject a discussion, study, or information concerns.','Noun + に関して + clause; noun + に関する + noun','Formal / written','Useful for a defined subject in reports or official communication.','Use に関する directly before a noun; に関して connects to a predicate.',[['契約[に関して]質問があります。','I have a question about the contract.','A defined subject.'],['環境[に関する]本を読んだ。','I read a book concerning the environment.','Modifying a noun.'],['調査の結果[に関して]説明します。','I will explain the survey results.','A formal presentation topic.']]),
p('n3-077','Take another person’s role or replace an earlier thing.','Noun + に代わって / に代わり','Neutral / formal','The replacement performs the relevant role or takes over its function.','代わりに can also express an exchange; に代わって highlights substitution.',[['部長[に代わって]私が説明します。','I will explain on behalf of the department head.','A representative role.'],['手紙[に代わって]メールが広く使われるようになった。','Email came to be widely used in place of letters.','A change in medium.'],['父[に代わり]、私が店を開けた。','I opened the shop in my father’s place.','Taking over a task.']]),
p('n3-078','Compare a feature against another person, thing, or time.','Noun + に比べて','Neutral','The compared items should share a sensible basis for comparison.','に比べて introduces the benchmark; it does not itself specify more or less.',[['去年[に比べて]、今年は雨が少ない。','Compared with last year, there is less rain this year.','A time comparison.'],['兄[に比べて]、私は背が低い。','I am shorter than my older brother.','A shared physical scale.'],['車[に比べて]、自転車は維持費が安い。','Compared with a car, a bicycle costs less to maintain.','Comparing one aspect.']]),
p('n3-079','Describe becoming accustomed to something through experience.','Noun + に慣れる; verb dictionary form + のに慣れる','Neutral','Use に慣れている for an already familiar state.','慣れる means get used to; it is not the same as becoming skilled at everything involved.',[['新しい生活[に慣れた]。','I got used to my new life.','A completed adjustment.'],['早く起きるの[に慣れている]。','I am used to getting up early.','An established habit.'],['左側を運転するの[に慣れる]まで時間がかかった。','It took time to get used to driving on the left.','Adjustment to a new practice.']]),
p('n3-080','Set a formal location, occasion, or field for a statement.','Noun + において + clause; noun + における + noun','Formal / written','Common in announcements, research, and official descriptions.','Use における before a noun; ordinary conversation usually uses で.',[['会議は本館[において]行われる。','The meeting will be held in the main building.','A formal location.'],['教育[における]技術の役割を考える。','We consider the role of technology in education.','A field modifying a noun.'],['今回の調査[において]新しい事実が分かった。','New facts emerged in this investigation.','A formal investigative setting.']]),
p('n3-081','Describe following a guide or a change that develops alongside another.','Noun / verb dictionary form + に従って','Neutral / written','With instructions it means follow; with changing events it means as.','For an instruction use a noun such as 指示; a verb clause usually describes linked change.',[['係員の指示[に従って]移動してください。','Please move as directed by the staff.','Following guidance.'],['山を登る[に従って]、気温が下がった。','The temperature fell as we climbed the mountain.','Two linked changes.'],['計画[に従って]作業を進めた。','We proceeded with the work according to the plan.','Following an established plan.']]),
p('n3-082','Accept a possibility while adding a condition or reservation.','Plain form + にしても; noun / な-adjective stem + にしても','Neutral','Often means even if or even taking that as true.','The following clause should respond to the assumed situation.',[['参加する[にしても]、少し遅れます。','Even if I participate, I will be a little late.','A condition on participation.'],['冗談[にしても]、言い方がひどい。','Even as a joke, that was a terrible way to put it.','A concession followed by criticism.'],['買わない[にしても]、見ておきたい。','Even if I do not buy it, I want to have a look.','An action worth doing either way.']]),
p('n3-083','Judge something as unexpected for a stated category or circumstance.','Plain form + にしては; noun / な-adjective stem + にしては','Neutral / evaluative','The first clause gives a known benchmark, not just a hypothetical.','子どもにしては can sound patronizing; use with care when praising someone.',[['冬[にしては]暖かい日だ。','It is a warm day for winter.','Seasonal expectations.'],['初めて作った[にしては]、よくできている。','It turned out well for a first attempt.','Experience as the benchmark.'],['安い[にしては]丈夫だ。','It is durable considering how cheap it was.','Price and expected quality.']]),
p('n3-084','Mark the target of an attitude or set two subjects in contrast.','Noun + に対して; clause + のに対して','Neutral / written','With a target it means toward; with contrasting clauses it means whereas.','Use の before に対して when attaching a full verb clause.',[['店員は客[に対して]丁寧に話した。','The clerk spoke politely to the customer.','Target of an attitude.'],['兄は静かなの[に対して]、弟はよく話す。','Whereas my older brother is quiet, my younger brother talks a lot.','Contrasting characteristics.'],['質問[に対して]、具体的な答えがなかった。','There was no specific answer to the question.','A response directed at something.']]),
p('n3-085','State whose perspective determines an evaluation.','Person / group noun + にとって','Neutral','Often followed by an evaluative word such as 大切, 難しい, or 必要.','Use に for an action directed to a recipient; にとって marks a viewpoint.',[['私[にとって]、この写真は宝物だ。','To me, this photograph is a treasure.','Personal value.'],['初心者[にとって]、この説明は難しい。','This explanation is difficult for beginners.','Difficulty from a group’s perspective.'],['地域[にとって]大切な行事だ。','It is an important event for the community.','Collective value.']]),
p('n3-086','Identify the topic of speech, thought, or investigation.','Noun + について; noun + についての + noun','Neutral','A broad topic marker, less formal than に関して.','Use についての before a noun such as 本 or 質問.',[['将来[について]話し合った。','We discussed the future.','A discussion topic.'],['日本の歴史[についての]本を借りた。','I borrowed a book about Japanese history.','A noun-modifying topic phrase.'],['この制度[について]調べています。','I am researching this system.','A research subject.']]),
p('n3-087','Describe one change developing together with another.','Change verb dictionary form / change noun + につれて','Neutral','Both clauses normally describe gradual change, not a deliberate instruction.','Use に従って for obeying guidance; につれて does not express that meaning.',[['日が暮れる[につれて]、寒くなった。','It got colder as evening fell.','Parallel gradual changes.'],['練習を重ねる[につれて]、自信がついた。','I gained confidence as I kept practicing.','Accumulated experience.'],['季節の変化[につれて]、店の商品も変わる。','The shop’s products change along with the seasons.','A noun expressing change.']]),
p('n3-088','State what is necessary or useful to achieve an action.','Verb dictionary form + には','Neutral','Commonly followed by 必要だ, いい, or a required time or resource.','This purpose use requires the dictionary form, not the verb stem.',[['この町で暮らす[には]、車があると便利だ。','A car is useful for living in this town.','A practical condition.'],['上達する[には]、毎日の練習が必要だ。','Daily practice is necessary to improve.','A requirement for progress.'],['駅まで歩く[には]、三十分かかる。','It takes thirty minutes to walk to the station.','A required amount of time.',{"三十分":"さんじゅっぷん"}]]),
p('n3-089','Identify the source of reported information.','Information source + によると / によれば','Neutral / reports','Often followed by そうだ, という, or another reporting form.','Naming a source does not establish the information as independently verified.',[['天気予報[によると]、明日は雪だそうだ。','According to the weather forecast, it will snow tomorrow.','A named forecast.'],['新聞[によれば]、橋は来月開通するという。','According to the newspaper, the bridge opens next month.','A written report.'],['友人の話[によると]、店は移転したらしい。','According to my friend, the shop seems to have moved.','An informal source.']]),
p('n3-090','Connect a result to its cause, method, agent, or varying condition.','Noun + によって; noun + による + noun','Neutral / formal','The intended relationship depends on the noun and predicate.','For everyday tools like a pen, で is usually more natural than によって.',[['台風[によって]橋が壊れた。','The bridge was damaged by the typhoon.','A cause.'],['支払い方法[によって]手数料が違う。','The fee varies depending on the payment method.','Variation by condition.'],['これは若い建築家[による]作品だ。','This is a work by a young architect.','An agent modifying a noun.']]),
p('n3-091','Ask for an explanation in a measured or reflective way.','Plain form + のでしょうか; noun / な-adjective + な + のでしょうか','Polite / reflective','Often softer than a direct question, but still asks for an account.','Use なのでしょうか after nouns; だのでしょうか is incorrect.',[['なぜ電車が止まった[のでしょうか]。','Why has the train stopped?','Seeking a reason.'],['この箱は何に使う[のでしょうか]。','What is this box used for?','A reflective inquiry.'],['本当にそれが必要な[のでしょうか]。','Is that really necessary?','Politely questioning an assumption.']]),
p('n3-092','Describe something organized around a central place, person, or concern.','Noun + を中心に / を中心として','Neutral / written','The center may be geographical or organizational.','This indicates a focus, not necessarily the exact physical middle.',[['駅[を中心に]店が集まっている。','Shops are clustered around the station.','A geographical hub.'],['若者[を中心に]人気が広がった。','Its popularity spread mainly among young people.','A central audience.'],['安全対策[を中心に]計画を見直した。','We reviewed the plan with safety measures as its main focus.','An organizing priority.']]),
p('n3-093','Name a representative first example before a broader group.','Noun + をはじめ; noun + をはじめとする + noun','Formal / neutral','The first item is prominent or representative; the list is not exhaustive.','This is an example-list expression, not the verb 始める meaning begin.',[['校長[をはじめ]、多くの先生が参加した。','Many teachers, including the principal, participated.','A prominent representative.'],['東京[をはじめとする]大都市で売られている。','It is sold in major cities including Tokyo.','A noun-modifying group.'],['茶道[をはじめ]、さまざまな文化を学んだ。','I studied various cultural traditions, including the tea ceremony.','One example among several.']]),
p('n3-094','Say that feeling or intention is put into an action or object.','Feeling noun + を込めて','Neutral / expressive','Common with 感謝, 心, 愛情, and 願い.','Do not use it simply for physically putting an object into a container.',[['感謝[を込めて]手紙を書いた。','I wrote a letter filled with gratitude.','Feeling expressed through writing.'],['願い[を込めて]木を植えた。','We planted a tree with a wish in our hearts.','An intention invested in an act.'],['心[を込めて]料理を作った。','I prepared the meal with care.','Sincere effort.']]),
p('n3-095','Describe an intermediary, shared experience, or a continuous time span.','Noun + を通じて / を通して','Neutral / written','Both forms mark a channel; を通して often emphasizes an active process.','For the entire span of a year, 一年を通じて means throughout, not just once.',[['友人[を通じて]彼を知った。','I got to know him through a friend.','A human intermediary.'],['旅[を通して]、考え方が変わった。','My way of thinking changed through travel.','Learning through experience.'],['この町は一年[を通じて]暖かい。','This town is warm throughout the year.','An entire time span.']]),
p('n3-096','Credit a helpful person, action, or condition for a good result.','Plain form + おかげで; noun + の / な-adjective + な + おかげで','Neutral / grateful','Usually positive; irony is possible but depends strongly on context.','Use せいで to straightforwardly blame an unwanted cause.',[['先生の[おかげで]、研究が進んだ。','Thanks to my teacher, my research progressed.','A person receives credit.'],['早く出た[おかげで]、電車に間に合った。','Thanks to leaving early, I caught the train.','A helpful prior action.'],['天気がよかった[おかげで]、写真がきれいに撮れた。','Thanks to the good weather, the photos came out well.','A favorable condition.']]),
p('n3-097','Describe leaving a state unchanged or continuing an action without a break.','Verb stem + っぱなし','Conversational','Often implies neglect or strain; some contexts are neutral.','つけっぱなし means leaving something on, not repeatedly switching it on.',[['電気をつけ[っぱなし]で寝てしまった。','I fell asleep with the light left on.','A neglected state.'],['朝から立ち[っぱなし]だ。','I have been standing since morning without a break.','Continuous activity.'],['本を借り[っぱなし]にしていた。','I had left the borrowed book unreturned.','An action without its expected follow-up.']]),
p('n3-098','Describe a noticeable quality, resemblance, or tendency.','Noun / selected verb stems + っぽい','Conversational','Forms an い-adjective; often mildly critical.','Not every verb permits っぽい; learn established forms such as 忘れっぽい.',[['この服は子ども[っぽい]。','These clothes look childish.','A resemblance.'],['最近、忘れ[っぽく]なった。','I have become forgetful lately.','A tendency.'],['このスープは水[っぽい]。','This soup is watery.','An excessive quality.']]),
p('n3-099','Include an unexpected extreme case with even.','Noun / particle phrase + さえ','Neutral / emphatic','Highlights an item the listener may have expected to be excluded.','さえ alone marks an extreme example; さえ〜ば gives a sufficient condition.',[['忙しくて昼ご飯[さえ]食べられなかった。','I was so busy I could not even eat lunch.','A basic need left unmet.'],['子どもに[さえ]分かる説明だ。','It is an explanation even children can understand.','An unexpected group.'],['名前[さえ]知らない人から手紙が来た。','I received a letter from someone whose name I do not even know.','A minimal detail is missing.']]),
p('n3-100','Present one condition as enough for the desired result.','Noun + さえ + conditional ば; verb stem + さえすれば','Neutral','Other requirements are treated as unimportant or already satisfied.','The condition must be framed conditionally, not as a simple affirmative statement.',[['時間[さえ]あれ[ば]、手伝えます。','As long as I have time, I can help.','Time is the remaining condition.'],['この薬を飲み[さえすれば]、大丈夫です。','You will be all right as long as you take this medicine.','A single sufficient action.'],['道[さえ]分かれ[ば]、一人で行ける。','As long as I know the way, I can go by myself.','One necessary piece of knowledge.',{"一人":"ひとり"}]]),
p('n3-101','Refer formally to an occasion when an action happens.','Verb dictionary / past form + 際に; noun + の際に','Formal / notices','Common in instructions and polite explanations of procedures.','For ordinary casual storytelling, とき is usually less stiff.',[['お帰りの[際に]、鍵をお返しください。','Please return the key when you leave.','A polite procedure.'],['申し込む[際に]、住所を記入してください。','Please enter your address when applying.','An application step.'],['出張の[際に]、現地の工場を見学した。','During my business trip, I visited the local factory.','A formal occasion.']]),
p('n3-102','Locate an interruption or event right in the middle of an activity.','Verb ている + 最中に; noun + の最中に','Neutral','Often introduces an unexpected or inconvenient event.','最中 emphasizes being in the midst, more strongly than a general とき.',[['会議の[最中に]電話が鳴った。','The phone rang in the middle of the meeting.','An interruption.'],['料理をしている[最中に]停電した。','The power went out while I was right in the middle of cooking.','An interrupted task.'],['試合の[最中に]雨が降り始めた。','It began raining in the middle of the match.','An event during ongoing activity.']]),
p('n3-103','Add something further or describe an increase beyond the current degree.','さらに + additional fact / increased degree','Neutral / written','Can connect sentences or intensify a changing situation.','It adds or increases; it does not introduce a contrast like しかし.',[['雨が[さらに]強くなった。','The rain became even heavier.','An increased degree.'],['料金には食事が含まれる。[さらに]、送迎もある。','The price includes meals. In addition, transport is provided.','An added benefit.'],['もう一度確認し、[さらに]修正した。','I checked it again and made further corrections.','Additional work.']]),
p('n3-104','Move the conversation or presentation to its next topic.','さて + new stage / topic','Neutral / presentations','Signals a transition or return to business; not a logical cause.','Use ところで for an unrelated conversational aside.',[['[さて]、次の問題に進みましょう。','Now, let us move to the next question.','A planned transition.'],['[さて]、今日の予定を確認します。','Well then, I will go over today’s schedule.','Beginning the main business.'],['[さて]、何から始めようか。','Now then, what shall we start with?','Preparing to act.']]),
p('n3-105','Attribute an unwanted result to a cause.','Plain form + せいで; noun + の / な-adjective + な + せいで','Neutral, often blaming','May express personal interpretation rather than proven causation.','Use おかげで when giving sincere credit for a good result.',[['寝不足の[せいで]、頭が痛い。','My head hurts because of lack of sleep.','An unwelcome physical result.'],['道が混んでいた[せいで]、遅刻した。','I was late because the road was crowded.','Explaining a delay.'],['私の[せいで]迷惑をかけた。','I caused trouble through my own fault.','Accepting blame.']]),
p('n3-106','Give an upper limit that is modest or less than expected.','せいぜい + amount / limit','Neutral, sometimes dismissive','May imply disappointment; distinguish from its encouragement use with effort verbs.','せいぜい十人 means ten at most, not at least ten.',[['参加者は[せいぜい]十人だろう。','There will probably be ten participants at most.','A modest upper estimate.'],['歩いても[せいぜい]十五分だ。','Even on foot, it takes at most fifteen minutes.','A reassuring limit.'],['私にできるのは[せいぜい]資料を集めることだ。','The most I can do is gather materials.','A limit on contribution.']]),
p('n3-107','Refer to a while whose length depends on the situation.','しばらく + action / state; しばらく + negative','Neutral','Can mean for a while, after a while, or not for some time.','It does not specify an exact duration; supply one separately if needed.',[['ここで[しばらく]待ちましょう。','Let us wait here for a while.','A short indefinite wait.'],['[しばらく]会っていませんね。','We have not seen each other for some time.','An interval without contact.'],['[しばらく]すると、雨がやんだ。','After a while, the rain stopped.','Time passes before an event.']]),
p('n3-108','Present an action as the only available choice.','Verb dictionary form + しかない','Neutral','Often implies resignation, but can also express determination.','Use the dictionary form: 待つしかない, not 待たないしかない.',[['終電がないので、歩く[しかない]。','There are no more trains, so we have no choice but to walk.','No available alternative.'],['ここまで来たら、やる[しかない]。','Having come this far, we just have to do it.','Determination.'],['返事が来るまで待つ[しかない]。','We can only wait until a reply comes.','A limited course of action.']]),
p('n3-109','Connect a prior circumstance to its consequence.','Situation。そのために + result','Neutral / explanatory','In this connective use その refers to the preceding situation; purpose is a separate reading.','Keep the preceding cause clear so it is not mistaken for “for that purpose.”',[['昨夜は雪が降った。[そのために]、道路が凍っている。','It snowed last night. As a result, the roads are frozen.','A physical consequence.'],['電車が故障した。[そのために]、到着が遅れた。','The train broke down. For that reason, our arrival was delayed.','A transport delay.'],['工場が閉鎖された。[そのために]、多くの人が仕事を失った。','The factory closed. As a result, many people lost their jobs.','A social consequence.']]),
p('n3-110','Offer another alternative in a question.','Question A。それとも + question B','Neutral','Normally connects alternatives being asked about, rather than plain statements.','Use それとも for “or” in questions; use あるいは for formal statements.',[['お茶にしますか。[それとも]、コーヒーにしますか。','Would you like tea? Or would you prefer coffee?','Two drink options.'],['歩いて行く？[それとも]バスに乗る？','Shall we walk, or take the bus?','A travel choice.'],['今日は家にいるの？[それとも]出かけるの？','Are you staying home today, or going out?','Asking about two plans.']]),
p('n3-111','Predict from the situation that an event is unlikely.','Verb stem + そうにない / そうもない','Neutral','A negative appearance judgment, often based on current clues.','雨が降らなそうだ uses another negative formation; avoid 降らないそうにない.',[['雨はやみ[そうにない]。','The rain does not look likely to stop.','A weather judgment.'],['今日は仕事が終わり[そうもない]。','It looks like I will not finish work today.','Current progress informs the prediction.'],['この箱は一人では運べ[そうにない]。','I do not think I can carry this box alone.','A judgment about ability.',{"一人":"ひとり"}]]),
p('n3-112','Mark something as already completed or established by a reference time.','すでに + completed action / state','Neutral / written','Often more formal than もう and stresses completion relative to a point in time.','It does not itself make a verb past; choose tense for the intended timeline.',[['会議は[すでに]始まっていた。','The meeting had already begun.','Before a past reference time.'],['その件は[すでに]確認しました。','I have already checked that matter.','A completed task.'],['チケットは[すでに]売り切れです。','The tickets are already sold out.','An established current state.']]),
p('n3-113','Restate something with a precise equivalent or definition.','Statement / term + すなわち + equivalent','Formal / written','The restatement should identify essentially the same thing.','For a loose conclusion or simplification, つまり is usually more natural.',[['一ダース、[すなわち]十二個を注文した。','I ordered one dozen, that is, twelve.','An exact numerical equivalent.'],['今日は春分の日、[すなわち]祝日だ。','Today is the spring equinox holiday, namely a public holiday.','Identifying a category.'],['母の姉、[すなわち]私の伯母が来る。','My mother’s older sister, in other words my aunt, is coming.','Two descriptions of one person.']]),
p('n3-114','Emphasize that an amount is at least as large as stated.','Quantity + は + predicate','Neutral','Context can imply that the actual amount may be greater.','This is a lower bound; せいぜい gives an upper bound.',[['駅まで二十分[は]かかる。','It takes at least twenty minutes to reach the station.','A minimum travel time.',{"二十分":"にじゅっぷん"}],['水は二リットル[は]用意しよう。','Let us prepare at least two liters of water.','A minimum supply.'],['会場には百人[は]いた。','There were at least a hundred people at the venue.','A confident lower estimate.']]),
p('n3-115','Recall a repeated past habit with reflection or nostalgia.','Verb past form + ものだ','Neutral / reflective','Often refers to a period well before the present and repeated activity.','A single completed event normally takes a plain past statement.',[['子どものころ、よく川で遊んだ[ものだ]。','As a child, I used to play in the river often.','A remembered habit.'],['学生時代は夜遅くまで話した[ものだ]。','In my student days, we used to talk late into the night.','Nostalgic repetition.'],['昔はこの道を毎日歩いた[ものだ]。','I used to walk along this road every day.','A routine recalled from the past.']]),
p('n3-116','Show that an unexpected event occurred immediately after another.','Verb past form + とたん（に）','Neutral / narrative','The following event is usually sudden and not a planned intention or request.','Avoid a volitional main clause such as “let us go” after たとたん.',[['窓を開けた[とたん]、強い風が入った。','The moment I opened the window, a strong wind blew in.','An immediate unexpected effect.'],['座った[とたんに]、電話が鳴った。','Just as I sat down, the phone rang.','A sudden interruption.'],['蛇口をひねった[とたん]、茶色い水が出た。','The moment I turned the tap, brown water came out.','An abrupt discovery.']]),
p('n3-117','Say that the same thing happens on every occasion.','Verb dictionary form + たびに; noun + のたびに','Neutral','Emphasizes recurring occasions rather than a scheduled interval.','Use ごとに for fixed intervals such as three hours.',[['この歌を聞く[たびに]、故郷を思い出す。','Whenever I hear this song, I remember my hometown.','A repeated emotional response.'],['旅行の[たびに]、切符を取っておく。','I keep the tickets every time I travel.','A personal ritual.'],['会う[たびに]、新しい話をしてくれる。','Every time we meet, she tells me a new story.','A repeated occasion.']]),
p('n3-118','State an intended purpose or a cause that explains a result.','Purpose: dictionary-form intentional verb + ために; noun + のために. Cause: plain clause + ために; noun + のために; な-adjective + なために.','Neutral / formal','Purpose ために presents a goal the action is directed toward. With causes, it explains a result, often in reports. ように often frames a desired state or ability; context and the speaker’s perspective matter.','Do not read every ために as because. Purpose and cause have different time relationships; a past cause can use 雨が降ったために.',[['大雪の[ために]、学校は休みになった。','School was closed because of heavy snow.','A reported cause.'],['連絡が遅れた[ために]、準備が間に合わなかった。','Because the message arrived late, the preparations were not ready in time.','A past cause and consequence.'],['日本で働く[ために]、日本語を勉強しています。','I am studying Japanese in order to work in Japan.','An intentional goal; ために describes the purpose rather than the cause.']]),
p('n3-119','Confirm a fact or concede a point before qualifying it.','確かに + claim','Neutral','Can strongly affirm or introduce a concession followed by が.','たしか often means if I remember correctly; 確かに is more definite.',[['[確かに]ここに置きました。','I definitely put it here.','Firm confirmation.'],['[確かに]安いが、品質は気になる。','It is certainly cheap, but I am concerned about the quality.','A concession.'],['その意見には[確かに]一理ある。','That opinion certainly has some merit.','Acknowledging a point.']]),
p('n3-120','Describe something just completed and still fresh.','Verb stem + たて; たての + noun','Neutral','Most natural with actions whose fresh result matters, such as cooking or arriving.','Not all verbs take たて; たばかり has a wider range.',[['焼き[たての]パンを買った。','I bought freshly baked bread.','Freshness affects quality.'],['入れ[たての]お茶はいかがですか。','Would you like some freshly brewed tea?','A fresh drink.'],['日本に来[たての]ころは、毎日迷った。','When I had just arrived in Japan, I got lost every day.','A newly begun stage of life.']]),
p('n3-121','Keep a conclusion unchanged even under an imagined condition.','たとえ + ても-form','Neutral','The condition may be hypothetical rather than something already true.','Pair たとえ with a concessive form such as ても, not a plain conditional result.',[['[たとえ]雨が降っ[ても]、出発する。','Even if it rains, we will set off.','An unchanged plan.'],['[たとえ]反対され[ても]、自分で決めたい。','Even if others oppose me, I want to decide for myself.','A hypothetical obstacle.'],['[たとえ]一人[でも]、最後まで続ける。','Even if I am alone, I will keep going to the end.','A noun with でも.',{"一人":"ひとり"}]]),
p('n3-122','Introduce one example of a broader idea.','例えば + example','Neutral','The example illustrates the category without exhausting all possibilities.','Use つまり for a restatement of the whole idea, rather than one example.',[['果物が好きです。[例えば]、梨や桃です。','I like fruit, for example pears and peaches.','Examples of a category.'],['[例えば]、この道を通れば十分で着きます。','For example, if we take this road, we will arrive in ten minutes.','An illustrative option.',{'十分':'じゅっぷん'}],['[例えば]明日なら、何時がいいですか。','For example, if we choose tomorrow, what time would suit you?','A possible scenario.',{"何時":"なんじ"}]]),
p('n3-123','Say casually that a condition still would not change the result.','Verb た-form + って; い-adjective stem + くたって / かったって; noun / な-adjective + だって','Casual','A contracted concessive form related to ても; not the hearsay だって.','行ったって here means even if you go, not someone said they went.',[['今から走っ[たって]、間に合わない。','Even if we run now, we will not make it.','An unchanged outcome.'],['安く[たって]、必要なければ買わない。','Even if it is cheap, I will not buy it unless I need it.','Adjective concessive.'],['子ども[だって]、その違いは分かる。','Even a child can understand that difference.','An unexpected included case.']]),
p('n3-124','Describe repeatedly doing one thing to the exclusion of others.','Verb て-form + ばかりいる','Neutral, often critical','Often implies an unbalanced habit, rather than a single continuous action.','寝てばかりいる means does little but sleep, not merely is sleeping now.',[['弟はゲームをし[てばかりいる]。','My younger brother does little but play games.','An unbalanced habit.'],['休みの日に寝[てばかりいる]と、体が重くなる。','If I do nothing but sleep on days off, my body feels sluggish.','A repeated pattern.'],['文句を言っ[てばかりいない]で、手伝って。','Stop just complaining and help.','Rejecting a repeated behavior.']]),
p('n3-125','Encourage someone to try an action and observe the result.','Verb て-form + ごらん','Familiar / gentle authority','Usually addressed to children, learners, or close subordinates.','Avoid using this toward a superior; てみてください is safer in polite guidance.',[['この窓から外を見[てごらん]。','Try looking outside through this window.','Inviting a discovery.'],['まず自分でやっ[てごらん]。','Try doing it yourself first.','Encouraging an attempt.'],['この音をよく聞い[てごらん]。','Listen carefully to this sound.','Guided attention.']]),
p('n3-126','Say that an experience first made something possible or clear.','Verb て-form + 初めて','Neutral','The first event is the necessary turning point for the realization or change.','This is more than doing something for the first time; the second clause explains what became clear.',[['親になっ[て初めて]、母の苦労が分かった。','Only after becoming a parent did I understand my mother’s hardships.','Experience brings understanding.'],['使っ[て初めて]、便利さが分かる。','You appreciate its convenience only after using it.','Direct experience reveals value.'],['一人で暮らし[て初めて]、家事の大変さを知った。','Only after living alone did I learn how demanding housework is.','A change in perspective.',{"一人":"ひとり"}]]),
p('n3-127','Make a first action a prerequisite for a later one.','Verb て-form + からでないと + negative result','Neutral','The main clause normally denies possibility or acceptability before the prerequisite.','Do not use an affirmative result where the meaning requires cannot yet.',[['予約し[てからでないと]、入れません。','You cannot enter until you have made a reservation.','An admission requirement.'],['実物を見[てからでないと]、決められない。','I cannot decide until I have seen the actual item.','Information needed for a decision.'],['許可をもらっ[てからでないと]、使ってはいけない。','You must not use it until you have received permission.','A required authorization.']]),
p('n3-128','Describe an intense feeling or sensation that is hard to control.','Verb / い-adjective て-form; な-adjective + で + しょうがない / しかたがない','Neutral / expressive','Usually subjective feelings and sensations, not a request or obligation.','寒くてしかたがない describes intense cold; てもしかたがない instead evaluates an action as futile.',[['眠く[てしょうがない]。','I am terribly sleepy.','A strong physical sensation.'],['結果が気になっ[てしかたがない]。','I cannot stop wondering about the result.','An insistent concern.'],['一人の夜は寂しく[てしょうがない]。','I feel terribly lonely on nights alone.','An intense emotion.',{"一人":"ひとり"}]]),
p('n3-129','Say that a limited action is enough to settle a matter.','Verb て-form + 済む; negative なくて / ないで / ずに + 済む','Neutral','Often expresses relief that a larger cost or action was unnecessary.','Use なくて済む for not needing to do something; て済む describes what suffices.',[['謝っ[て済む]問題ではない。','This is not a problem that an apology will settle.','A limited action is insufficient.'],['部品を替え[て済んだ]。','It was enough to replace the part.','A modest repair sufficed.'],['雨がやんだので、傘を買わ[ずに済んだ]。','The rain stopped, so I did not need to buy an umbrella.','An avoided action.']]),
p('n3-130','Explain a precaution by naming the outcome that must be avoided.','Verb て-form + はいけないから','Neutral','Here てはいけない refers to an undesirable outcome, not necessarily a rule directed at someone.','Be explicit about the precaution; the phrase supplies its reason.',[['風邪をひい[てはいけないから]、上着を持っていこう。','Let us take jackets so that we do not catch a cold.','Preventing an unwanted outcome.'],['電車に遅れ[てはいけないから]、早く出よう。','Let us leave early so that we do not miss the train.','A time precaution.'],['忘れ[てはいけないから]、メモしておく。','I will make a note so that I do not forget.','A memory aid.']]),
p('n3-131','Say that the present situation calls for something more urgent.','Verb ている + 場合じゃない / 場合ではない','Conversational / urgent','Often rebukes an inappropriate action or redirects one’s own attention.','It concerns what is appropriate now, not whether the action is physically possible.',[['笑っ[ている場合じゃない]。','This is no time to laugh.','Urgent redirection.'],['迷っ[ている場合ではない]。すぐ決めよう。','This is no time to hesitate. Let us decide now.','An immediate decision is needed.'],['テレビを見[ている場合じゃない]。明日は試験だ。','This is no time to watch television. The exam is tomorrow.','A more pressing task.']]),
p('n3-132','Turn a noun into a description of a quality, relation, or approach.','Selected noun + 的; 的な + noun; 的に + predicate','Neutral / often written','Use established combinations such as 具体的, 科学的, and 積極的.','Not every noun can freely take 的; the result behaves like a な-adjective.',[['もっと具体[的に]説明してください。','Please explain more concretely.','Describing how to explain.'],['科学[的な]方法で調べる。','We investigate using a scientific method.','Modifying a noun.'],['彼は活動に積極[的だ]。','He participates enthusiastically in activities.','A predicate adjective.']]),
p('n3-133','Say that an action will not help move the situation forward.','Verb て-form + も始まらない','Neutral / conversational','Often discourages worrying, complaining, or dwelling on the past.','It means there is no point, not that an event literally cannot begin.',[['今さら後悔し[ても始まらない]。','There is no use regretting it now.','Redirecting attention from the past.'],['文句を言っ[ても始まらない]から、直そう。','Complaining will not help, so let us fix it.','Moving toward action.'],['ここで悩んでい[ても始まらない]。','Staying here worrying will get us nowhere.','An unproductive state.']]),
p('n3-134','Give permission or say that a choice causes no problem.','Verb / adjective ても-form; noun / な-adjective + でも + 構わない','Neutral / polite','Permission can sound detached; context determines warmth.','For asking permission add ですか; the declarative form grants or accepts it.',[['ここに座っ[ても構いません]か。','Would it be all right if I sat here?','Asking permission.'],['少し遅れ[ても構わない]。','It does not matter if you are a little late.','Accepting a possibility.'],['コピー[でも構いません]。','A copy is fine.','Accepting an alternative form.']]),
p('n3-135','Say that an action is futile or cannot improve the situation.','Verb て-form + もしょうがない / もしかたがない','Neutral / conversational','Often encourages acceptance, sometimes with a resigned tone.','Unlike てしょうがない, this includes も and evaluates the usefulness of an action.',[['終わったことを責め[てもしょうがない]。','There is no point blaming someone for what is over.','An unhelpful response.'],['来ない人を待っ[てもしかたがない]。','There is no use waiting for someone who is not coming.','A futile action.'],['一人で心配し[てもしょうがない]から、相談しよう。','There is no use worrying alone, so let us ask for advice.','Choosing a productive response.',{"一人":"ひとり"}]]),
p('n3-136','Use a mentioned subject to bring a related thought into the conversation.','Topic + といえば','Neutral / conversational','Often responds to a topic already mentioned or readily shared.','It introduces an association, not a definition that must be exact.',[['京都[といえば]、古い寺を思い出す。','Speaking of Kyoto, I think of old temples.','A familiar association.'],['夏[といえば]、子どものころの海を思い出す。','Speaking of summer, I remember the sea from my childhood.','A personal memory.'],['映画[といえば]、新しい作品を見た？','Speaking of movies, have you seen the new one?','A related conversational turn.']]),
p('n3-137','Express a hope or gently suggest a favorable outcome.','Plain nonpast + といい; たら-form + いい','Neutral / friendly','For hopes outside one’s direct control; advice depends on context.','An unqualified hope about your own deliberate action is less natural than an intention.',[['明日、晴れる[といい]ね。','I hope it is sunny tomorrow.','A shared hope.'],['試験に合格でき[たらいい]な。','I hope I can pass the exam.','A personal wish about a result.'],['疲れているなら、少し休ん[だらいい]。','If you are tired, you could rest a little.','A gentle suggestion.']]),
p('n3-138','Qualify a statement to prevent an exaggerated interpretation.','Plain form + といっても; noun / な-adjective stem + といっても','Neutral','The first description is accepted, then its actual extent is narrowed.','It does not completely deny the first description; it corrects what might be inferred.',[['旅行[といっても]、隣の町へ行くだけだ。','It is a trip, but only to the next town.','Limiting the scale.'],['料理ができる[といっても]、簡単な物だけです。','I can cook, but only simple things.','Qualifying ability.'],['春[といっても]、まだ寒い。','It may be spring, but it is still cold.','Correcting an expected implication.']]),
p('n3-139','Report information or state the meaning inferred from it.','Plain form + ということだ','Neutral / explanatory','Can introduce hearsay or summarize what a situation implies; context separates them.','Do not automatically treat every occurrence as a reported quotation.',[['店は来月閉まる[ということだ]。','I hear the shop will close next month.','A reported fact.'],['返事がないなら、まだ決まっていない[ということだ]。','If there is no reply, that means it has not been decided yet.','An inferred meaning.'],['つまり、全員が賛成した[ということですね]。','So that means everyone agreed, right?','Checking a summary.']]),
p('n3-140','Introduce a term or idea and explain what it means.','Term / quoted clause + というのは + explanation','Neutral / explanatory','Can define a word or unpack an abstract statement.','For a plain noun topic, は often suffices; というのは calls attention to the expression.',[['「無料」[というのは]、お金がかからないという意味です。','“Free” means that no money is required.','Defining a term.'],['責任を持つ[というのは]、最後まで引き受けることだ。','Taking responsibility means seeing something through to the end.','Explaining an idea.'],['彼が来ない[というのは]、本当ですか。','Is it true that he is not coming?','Making a reported claim the topic.']]),
p('n3-141','Prompt an association or check what someone means by a topic.','Topic + というと','Neutral / conversational','Can lead to a familiar association or a clarification question.','A following question often asks for clarification rather than making a firm claim.',[['冬[というと]、鍋料理を思い出す。','When you mention winter, I think of hot-pot dishes.','A seasonal association.'],['先生[というと]、山田先生のことですか。','When you say the teacher, do you mean Professor Yamada?','Checking the referent.'],['危険[というと]、どんな危険ですか。','When you say danger, what kind of danger do you mean?','Requesting a clearer meaning.']]),
p('n3-142','Replace a description with one that fits more accurately.','Description A + というより + description B','Neutral','Often offers a refinement rather than an absolute denial of A.','Unlike よりも, this compares labels or descriptions, not simply quantities.',[['寒い[というより]、涼しい。','It is cool rather than cold.','Refining degree.'],['彼は先生[というより]、友人のような存在だ。','He is more like a friend than a teacher.','Refining a relationship.'],['驚いた[というより]、ほっとした。','I felt relieved rather than surprised.','Choosing the better emotional description.']]),
p('n3-143','Infer an explanation from observable signs.','Plain form + とみえる / とみえて','Written / somewhat formal','とみえて connects the inference to a visible result; usually concerns someone else or an external situation.','It is an inference, not a direct statement of the person’s private feelings.',[['疲れている[とみえて]、彼はすぐ眠った。','He appeared tired, as he fell asleep immediately.','Behavior supports an inference.'],['誰もいない[とみえて]、家は静かだった。','Apparently no one was there, as the house was quiet.','A quiet house as evidence.'],['道に迷った[とみえる]。同じ所を歩いている。','They appear to have lost their way. They keep walking around the same place.','An inferred explanation.']]),
p('n3-144','Consider what follows if a proposed situation is true.','Plain form + とすれば / としたら / とすると','Neutral','とすると often frames a logical inference; としたら often introduces an imagined case.','The assumption is provisional and does not confirm the first clause.',[['明日休みだ[としたら]、何をしたい？','If tomorrow were a day off, what would you like to do?','An imagined situation.'],['彼の話が本当だ[とすれば]、急ぐ必要がある。','If his account is true, we need to hurry.','A provisional premise.'],['今出た[とすると]、着くのは六時ごろだ。','If he left now, he would arrive around six.','A calculated consequence.']]),
p('n3-145','Connect companionship, simultaneous change, or two coexisting aspects.','Noun / verb dictionary form / い-adjective / な-adjectiveである + と共に','Formal / written','With change verbs it means as; with people it means together with.','For everyday invitations, と一緒に is usually more conversational.',[['家族[と共に]新しい町へ移った。','I moved to a new town with my family.','Companionship.'],['時代が変わる[と共に]、言葉も変わる。','Language changes as the times change.','Parallel change.'],['卒業はうれしい[と共に]、少し寂しい。','Graduating makes me happy and also a little sad.','Coexisting feelings.']]),
p('n3-146','Locate an event partway through a journey or activity.','Verb dictionary form + 途中で / 途中に; noun + の途中で / の途中に','Neutral','途中で often introduces an event; 途中に can identify a place along a route.','It marks a stage before completion, not necessarily the exact midpoint.',[['帰る[途中で]、友人に会った。','I met a friend on my way home.','An event along a route.'],['仕事の[途中で]休憩した。','I took a break partway through work.','An interrupted activity.'],['駅へ行く[途中に]、小さな橋がある。','There is a small bridge on the way to the station.','A location along the route.']]),
p('n3-147','Introduce a new topic or a conversational aside.','ところで + new topic','Conversational / neutral','Usually the new topic is only loosely connected to the previous one.','This connective differs from verb past + ところで meaning even if.',[['[ところで]、明日の集合は何時？','By the way, what time are we meeting tomorrow?','A new practical topic.',{"何時":"なんじ"}],['[ところで]、お兄さんは元気ですか。','By the way, how is your older brother?','A conversational aside.'],['[ところで]、この近くに銀行はありますか。','By the way, is there a bank nearby?','Changing to a question.']]),
p('n3-148','Introduce an actual result that runs counter to expectations.','Sentence。ところが + unexpected fact','Neutral / narrative','The following clause normally reports what happened, rather than giving a command or wish.','Use ところで for a topic change; ところが creates a surprise contrast.',[['晴れると思った。[ところが]、午後から雪になった。','I thought it would be sunny. However, it turned to snow in the afternoon.','Unexpected weather.'],['店に着いた。[ところが]、もう閉まっていた。','I arrived at the shop. But it was already closed.','An unwelcome discovery.'],['簡単だと思った。[ところが]、三時間もかかった。','I thought it would be easy. But it took three hours.','A result contradicting an estimate.']]),
p('n3-149','Describe acting exactly as a model, instruction, or expectation specifies.','Verb dictionary / past form + とおりに; noun + のとおりに / noun + どおりに','Neutral','The model provides the pattern that the action follows.','Use のとおり after a noun, or an established どおり compound such as 予定どおり.',[['先生が言った[とおりに]、線を引いた。','I drew the line as the teacher instructed.','Following instructions.'],['見本の[とおりに]折ってください。','Please fold it just like the sample.','Following a visual model.'],['予定[どおりに]出発した。','We departed as scheduled.','Matching a plan.']]),
p('n3-150','Keep doing an action consistently through to the end.','Verb stem + 通す','Neutral','Often emphasizes persistence despite difficulty, more than merely finishing an amount.','Use established action combinations; this suffix does not simply mean pass through a place.',[['最後まで自分の考えを言い[通した]。','I maintained my position to the end.','Persistence in an opinion.'],['一晩中、寝ないで見張り[通した]。','I kept watch all night without sleeping.','Sustained action.'],['彼女は約束を守り[通した]。','She kept her promise all the way through.','Consistency over time.']]),
p('n3-151','State the role, capacity, or status in which someone acts.','Noun + として; noun + としての + noun','Neutral','Names a role rather than an individual’s personal perspective.','にとって means from someone’s viewpoint; として means in a capacity.',[['通訳[として]会議に参加した。','I took part in the meeting as an interpreter.','A working role.'],['これは記念品[として]残しておく。','I will keep this as a memento.','A thing’s function.'],['親[としての]責任を感じる。','I feel my responsibility as a parent.','A noun-modifying role.']]),
p('n3-152','Strongly deny that an action is feasible in the circumstances.','とても + negative potential / negative predicate','Neutral / emphatic','Often expresses practical or emotional impossibility, not lack of effort alone.','とても is an intensifier here; the negative is essential to the cannot meaning.',[['この荷物は[とても]一人では運べ[ない]。','I could not possibly carry this luggage alone.','A physical limit.',{"一人":"ひとり"}],['そんな値段では[とても]買え[ない]。','I cannot possibly buy it at that price.','A financial limit.'],['彼のようには[とても]走れ[ない]。','I could never run like he does.','A limit of ability.']]),
p('n3-153','Reject a statement as a universal rule while allowing it in some cases.','Plain form + とは限らない','Neutral','Often paired with 必ずしも; it leaves room for exceptions.','It does not assert that the opposite is always true.',[['高い物がよい[とは限らない]。','Expensive things are not necessarily good.','Rejecting a generalization.'],['努力すれば必ず成功する[とは限らない]。','Effort does not always guarantee success.','Allowing exceptions.'],['明日も晴れる[とは限らない]。','It will not necessarily be sunny tomorrow too.','An uncertain continuation.']]),
p('n3-154','Describe an unplanned action that happens through impulse or habit.','つい + action; often てしまう','Neutral / conversational','Often implies mild regret or surprise at one’s own behavior.','ついに marks an eventual outcome; つい marks an unintended action.',[['面白くて、[つい]笑ってしまった。','It was so funny that I laughed without meaning to.','An involuntary response.'],['買い物に行くと、[つい]お菓子を買う。','When I go shopping, I end up buying sweets.','An impulsive habit.'],['[つい]本当のことを言ってしまった。','I let the truth slip out.','An unintended disclosure.']]),
p('n3-155','Mark an outcome reached after a long period or repeated developments.','ついに + result','Neutral / expressive','Can introduce a welcome achievement or an unwelcome final outcome.','とうとう is similar; ついに does not inherently mean success.',[['何年も練習して、[ついに]優勝した。','After years of practice, I finally won the championship.','A long-awaited achievement.'],['古い時計が[ついに]止まった。','The old clock finally stopped.','An unwelcome endpoint.'],['探していた本を[ついに]見つけた。','I finally found the book I had been looking for.','A search reaches its goal.']]),
p('n3-156','Add a convenient extra action while already doing something else.','Verb dictionary / past form + ついでに; noun + のついでに','Neutral','The extra action is secondary and convenient on that occasion.','It is not simply simultaneous action; use ながら when two actions overlap in time.',[['郵便局へ行く[ついでに]、パンを買った。','While I was out going to the post office, I bought some bread.','A convenient extra errand.'],['買い物の[ついでに]、図書館に寄る。','I will stop at the library while I am out shopping.','An additional stop.'],['棚を片付けた[ついでに]、窓も拭いた。','After tidying the shelf, I took the opportunity to wipe the window too.','Extending a household task.']]),
p('n3-157','Restate the main meaning or draw a concise conclusion.','Statement。つまり + summary / conclusion','Neutral','The new wording should make the earlier point clearer or shorter.','For one illustrative member of a group, use 例えば instead.',[['兄も妹も来ない。[つまり]、私一人だ。','Neither my older brother nor my younger sister is coming. In other words, I will be alone.','Drawing a simple conclusion.',{"一人":"ひとり"}],['会費は千円、食事は別料金です。[つまり]、全部で千円ではありません。','The membership fee is one thousand yen and meals cost extra. That means the total is not just one thousand yen.','Clarifying a cost.'],['彼は父の弟、[つまり]私の叔父です。','He is my father’s younger brother, in other words my uncle.','A simpler relationship label.']]),
p('n3-158','Recall an earlier intention, often one that did not happen.','Verb dictionary / negative form + つもりだった','Neutral','A following contrast often explains why the plan changed.','This describes a past intention, not proof that the action was completed.',[['今日は休む[つもりだった]が、仕事が入った。','I had intended to rest today, but work came up.','A changed plan.'],['電話する[つもりだった]のに、忘れてしまった。','I meant to call, but I forgot.','An unrealized intention.'],['何も買わない[つもりだった]。','I had intended not to buy anything.','A past negative intention.']]),
p('n3-159','Act with an assumed role or imagined situation in mind.','Plain form + つもりで; noun + の / な-adjective + な + つもりで','Neutral','The imagined frame guides the action; it need not be literally true.','This can mean “as if,” rather than an ordinary future plan.',[['先生になった[つもりで]説明してみて。','Try explaining it as if you were the teacher.','An assumed role.'],['旅行した[つもりで]、その分のお金を貯めた。','I saved that amount of money as if I had spent it on a trip.','An imagined alternative use of money.'],['本番の[つもりで]練習しよう。','Let us practice as though this were the real performance.','A mental frame for practice.']]),
p('n3-160','Act before a state changes, or describe change occurring during an activity.','Plain form + うちに; noun + の / な-adjective + な + うちに','Neutral','With an opportunity, the state must still hold; with ongoing activity, change may happen unnoticed.','Use 間 for a simple duration; うちに often highlights a changing opportunity or result.',[['温かい[うちに]食べてください。','Please eat it while it is still warm.','An opportunity before change.'],['日本にいる[うちに]、京都へ行きたい。','I want to go to Kyoto while I am in Japan.','A limited opportunity.'],['何度も聞く[うちに]、歌を覚えた。','As I listened repeatedly, I learned the song.','Gradual change during repetition.']]),
p('n3-161','Set a completed action as the basis for a next step, or name the aspect being considered.','Verb past form + 上で; verb dictionary form + 上で; noun + の上で','Neutral / formal','Past + 上で means after doing; dictionary form + 上で means in doing or for doing.','Changing the verb tense changes the relation, not just the timeline.',[['内容を確認した[上で]、署名してください。','Please sign after checking the contents.','A deliberate first step.'],['働く[上で]、健康は大切だ。','Good health is important in working life.','An aspect of activity.'],['地図の[上では]、駅は近く見える。','On the map, the station looks close.','The basis for a judgment.']]),
p('n3-162','Add another characteristic that strengthens the same evaluation.','Plain form + 上に; noun + の / な-adjective + な + 上に','Neutral','Usually combines positive with positive or negative with negative.','Use のに or が for a contrast rather than stacking opposing evaluations.',[['この店は安い[上に]、おいしい。','This restaurant is inexpensive and serves delicious food.','Two positive qualities.'],['雨が降った[上に]、風も強くなった。','It rained, and on top of that the wind grew strong.','Two difficulties.'],['彼女は親切な[上に]、説明も分かりやすい。','She is kind, and her explanations are also easy to follow.','Added praise.']]),
p('n3-163','Set one issue aside to consider another.','Noun + は別として; clause + かどうかは別として','Neutral','The set-aside issue is not necessarily unimportant or permanently dismissed.','It does not deny the first issue; it temporarily separates it from the discussion.',[['値段[は別として]、形は気に入った。','Leaving the price aside, I liked the shape.','Considering design separately.'],['成功するかどうか[は別として]、試してみたい。','Whether it succeeds or not aside, I want to try.','Separating outcome from willingness.'],['冗談[は別として]、本当の予定を教えて。','Joking aside, tell me your actual plans.','Returning to a serious topic.']]),
p('n3-164','Treat one item as obvious and add another beyond it.','Noun / nominalized clause + はもちろん','Neutral','Often followed by a second item marked with も or まで.','The second fact is an addition, not a contradiction of the first.',[['彼は英語[はもちろん]、中国語も話せる。','He speaks Chinese as well as, of course, English.','An added language ability.'],['この店は味[はもちろん]、雰囲気もいい。','This restaurant has a good atmosphere as well as good food.','Two appealing aspects.'],['週末[はもちろん]、平日も混んでいる。','It is crowded on weekdays as well as weekends.','Extending the expected range.']]),
p('n3-165','Identify what a person or place is known for.','Topic + は + reason / feature noun + で有名だ','Neutral','で gives the feature behind the reputation; it does not mark the location of fame.','Use として有名 for being famous in a role, such as 作家として.',[['この町[は]温泉[で有名]だ。','This town is famous for its hot springs.','A local feature.'],['彼女[は]美しい声[で有名]だ。','She is famous for her beautiful voice.','A personal quality.'],['あの店[は]大きなパン[で有名]です。','That shop is famous for its large loaves of bread.','A distinctive product.']]),
p('n3-166','Present a conclusion that follows naturally from known facts.','Plain form + わけだ; noun / な-adjective + な + わけだ','Neutral / explanatory','Often signals that a new fact makes the situation understandable.','Use わけだ for “that explains it,” not a prediction without a basis.',[['暖房が止まっていた。寒い[わけだ]。','The heating had stopped. That explains why it was cold.','A newly understood cause.'],['毎日十ページなら、一月で三百ページ読む[わけだ]。','At ten pages a day, that works out to three hundred pages in a month.','A logical calculation.'],['彼はこの町で育った。道に詳しい[わけだ]。','He grew up in this town. No wonder he knows the streets well.','An explained ability.']]),
p('n3-167','Correct a conclusion or deny that it applies without qualification.','Plain form + わけではない; noun / な-adjective + な + わけではない','Neutral','May mean not necessarily or it is not that, depending on what is being denied.','It need not deny every instance; it often rejects an overgeneralization.',[['嫌いな[わけではない]が、今日は食べたくない。','It is not that I dislike it; I just do not want to eat it today.','Correcting a reason.'],['全員が賛成した[わけではない]。','Not everyone agreed.','A partial denial.'],['高ければよい[わけではない]。','Being expensive does not necessarily make something good.','Rejecting a simple rule.']]),
p('n3-168','Strongly reject a possibility as impossible or unreasonable.','Plain form + わけがない; noun / な-adjective + な + わけがない','Neutral / emphatic','Expresses the speaker’s strong judgment, often based on what they know.','It is stronger than かもしれない in the negative; use carefully when evidence is limited.',[['鍵がないのに、入れる[わけがない]。','There is no way we can get in without a key.','A clear practical obstacle.'],['彼が約束を忘れる[わけがない]。','There is no way he would forget the promise.','Confidence in someone.'],['一日で全部覚えられる[わけがない]。','There is no way I can memorize all of it in one day.','Rejecting an unrealistic demand.']]),
p('n3-169','Say that responsibility or circumstances prevent an otherwise possible action.','Verb dictionary form + わけにはいかない; negative form + わけにはいかない','Neutral','Negative verb + わけにはいかない means one cannot avoid doing it.','This is a social or situational constraint, not simple physical inability.',[['明日は試験だから、遊ぶ[わけにはいかない]。','I have an exam tomorrow, so I cannot go out and have fun.','A responsibility takes priority.'],['秘密なので、話す[わけにはいきません]。','It is confidential, so I cannot tell you.','An obligation to others.'],['招待されたので、行かない[わけにはいかない]。','I was invited, so I cannot simply not go.','A double negative creates an obligation.']]),
p('n3-170','Compare a result with what its circumstances would lead one to expect.','Plain form + 割に; noun + の / な-adjective + な + 割に','Neutral','Often notes a surprising balance, such as good quality relative to low price.','Unlike に比べて, the comparison is with an expectation linked to a circumstance.',[['安い[割に]、よくできている。','It is well made considering how cheap it is.','Quality relative to price.'],['年齢の[割に]、体力がある。','She has a lot of stamina for her age.','A contextual benchmark.'],['たくさん食べた[割に]、お腹がすいている。','I feel hungry considering how much I ate.','An unexpected result.']]),
p('n3-171','Make clear that an action or result was intentional.','わざと + deliberate action','Neutral','Often concerns a misleading, provocative, or apparently accidental action.','わざわざ means taking special trouble; わざと means on purpose.',[['彼は[わざと]負けた。','He lost on purpose.','A deliberate result.'],['聞こえたが、[わざと]返事をしなかった。','I heard, but deliberately did not answer.','Intentional non-response.'],['驚かせようと、[わざと]足音を立てなかった。','I deliberately walked quietly to surprise them.','A planned effect.']]),
p('n3-172','Describe taking special trouble to do something.','わざわざ + action','Neutral, often grateful','Can also imply unnecessary trouble when used critically or with a negative.','It is not simply on purpose; some extra effort or detour is implied.',[['[わざわざ]来てくださって、ありがとうございます。','Thank you for taking the trouble to come.','Gratitude for effort.'],['彼は[わざわざ]駅まで迎えに来てくれた。','He went out of his way to meet me at the station.','A helpful extra effort.'],['それだけのために[わざわざ]出かけなくてもいい。','You do not need to make a special trip just for that.','Unnecessary effort.']]),
p('n3-173','Compare two things while giving added emphasis to the comparison.','Comparison noun / verb plain form + よりも','Neutral','も strengthens the contrast; より alone often expresses the same basic comparison.','The phrase before よりも is the benchmark, not the more highly rated item.',[['今日は昨日[よりも]暖かい。','Today is warmer than yesterday.','Comparing two days.'],['私は車[よりも]電車が好きだ。','I prefer trains to cars.','A preference.'],['話を聞く[よりも]、自分で試したい。','I would rather try it myself than hear about it.','Comparing actions.']]),
p('n3-174','Say that there is no available way to perform an action.','Verb stem + ようがない','Neutral','Often a missing resource or information makes the method unavailable.','よう here means way or means; it is not the volitional ending.',[['住所が分からないので、送り[ようがない]。','I do not know the address, so I have no way to send it.','Missing information.'],['部品がないから、直し[ようがない]。','There are no parts, so there is no way to repair it.','Missing resources.'],['証拠がなければ、確かめ[ようがない]。','Without evidence, there is no way to verify it.','No available method.']]),
p('n3-175','Express a tentative impression rather than a confident claim.','Plain form + ような気がする; noun + の / な-adjective + な + ような気がする','Neutral / cautious','Often based on memory, sensation, or an uncertain intuition.','It weakens the claim; it does not provide evidence that the impression is true.',[['前にも会った[ような気がする]。','I feel as though we have met before.','An uncertain memory.'],['今日は少し暖かい[ような気がする]。','It seems a little warmer today.','A subjective sensation.'],['この方法の方が簡単な[ような気がする]。','I have a feeling this method is easier.','A tentative evaluation.']]),
p('n3-176','Give an aim involving an attainable state or prevention.','Verb dictionary / potential / negative form + ように','Neutral','Often used where the goal is a state, ability, or event not directly controlled by a single action.','For a direct intentional action with the same agent, ために may be more natural.',[['聞こえる[ように]、大きな声で話した。','I spoke loudly so that I could be heard.','An intended ability.'],['忘れない[ように]、手帳に書いた。','I wrote it in my planner so that I would not forget.','Preventing an unwanted state.'],['早く治る[ように]、十分休んでください。','Please rest well so that you recover quickly.','A hoped-for condition.']]),
p('n3-177','Describe an appearance without asserting that it is reality.','Plain form + ように見える; noun + の / な-adjective + な + ように見える','Neutral','Usually rests on visible appearance, though a broader impression is possible.','元気に見える directly uses an adjective adverb; 元気なように見える uses the full pattern.',[['この岩は人の顔の[ように見える]。','This rock looks like a human face.','A visual resemblance.'],['彼は何か探している[ように見える]。','He appears to be looking for something.','An inferred activity.'],['写真では、部屋が広い[ように見える]。','In the photograph, the room looks spacious.','Appearance may differ from reality.']]),
p('n3-178','Describe someone making no attempt or showing no willingness to act.','Verb volitional form + としない','Neutral, often critical','Commonly describes another person’s observable unwillingness, rather than inability.','Compare ようとする, which marks an attempt or an imminent action.',[['弟は野菜を食べ[ようとしない]。','My younger brother will not even try to eat vegetables.','A lack of willingness.'],['彼は理由を話そ[うとしなかった]。','He made no attempt to explain the reason.','A refusal to disclose.'],['犬が小屋から出[ようとしない]。','The dog will not come out of its kennel.','Observed reluctance.']]),
p('n3-179','Describe trying to act or being just about to begin.','Verb volitional form + とする','Neutral','With intentional verbs it often means attempt; context can place an event just before its start.','This construction describes an attempt, not necessarily a successful result.',[['ドアを開け[ようとした]が、鍵がかかっていた。','I tried to open the door, but it was locked.','An unsuccessful attempt.'],['家を出[ようとした]とき、電話が鳴った。','The phone rang just as I was about to leave home.','An imminent action interrupted.'],['猫が棚に登ろ[うとしている]。','The cat is trying to climb onto the shelf.','An attempt in progress.']]),
p('n3-180','Describe doing something without performing another action.','Verb negative stem + ずに; する → せずに','Neutral / written','Often a more written alternative to ないで; subjects usually match.','The irregular form is せずに, not しずに.',[['朝ご飯を食べ[ずに]出かけた。','I went out without eating breakfast.','An omitted prior action.'],['辞書を使わ[ずに]読んでみた。','I tried reading without using a dictionary.','An action without a tool.'],['何も確認[せずに]返事をしてしまった。','I replied without checking anything.','The irregular する form.']]),
p('n3-181','Describe an impulse or response that is impossible to suppress.','Verb negative stem + ずにはいられない; する → せずにはいられない','Neutral / expressive','Usually feelings drive the action; can describe another person through visible evidence.','It expresses cannot help doing, not an external duty like なければならない.',[['その話を聞いて、笑わ[ずにはいられなかった]。','I could not help laughing when I heard that story.','An involuntary reaction.'],['美しい景色を見ると、写真を撮ら[ずにはいられない]。','When I see beautiful scenery, I cannot resist taking a photograph.','A strong impulse.'],['友人のことが心配で、連絡[せずにはいられなかった]。','I was so worried about my friend that I had to get in touch.','An emotionally compelled action.']]),
p('n3-182','Distribute equal amounts or describe change in small steps.','Quantity / 少し + ずつ','Neutral','Each unit receives the stated amount, or the amount advances step by step.','三個ずつ means three each; it does not mean three altogether.',[['一人に二枚[ずつ]配ってください。','Please hand out two sheets to each person.','Equal distribution.',{"一人":"ひとり"}],['毎日少し[ずつ]読んでいる。','I read a little each day.','Gradual progress.'],['箱を一つ[ずつ]運んだ。','I carried the boxes one at a time.','A repeated unit.']]),
];
